COLLDATA("najm","ur",[[1451,"انہی سے روایت ہے کہ ایک آدمی نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم! گزشتہ رات مجھے بچھو کے ڈنک مارنے کی وجہ سے بہت تکلیف ہوئی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: جب شام ہوئی تھی، اگر تو اس وقت یہ کہ لیتا: ((أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ)) ”میں اللہ کے کامل کلمات کی پناہ میں آتا ہوں اس چیز کے شر سے جو اُس نے پیدا کی ہے۔ تو مجھے اس سے تکلیف نہ پہنچتی۔“ (مسلم)","",{"k":"مسلم (۲۷۰۹)، احمد (۸۸۸۰)۔","e":"یہ یاد رہے یہ کلمات صبح و شام تین تین مرتبہ کہے جائیں۔","m":"لَدَغَتْهُ (منع) صحیح) واحد مونث غائب ماضی معلوم ضمیر مفعول یہ۔ اس نے ڈسا۔"}],[1452,"انہی سے روایت ہے کہ انہوں نے فرمایا: جب صبح ہوتی تو نبی صلی اللہ علیہ وسلم فرمایا کرتے تھے: ((اللَّهُمَّ بِكَ أَصْبَحْنَا، وَبِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ النُّشُورُ)) ”یا اللہ! تیرے نام سے ہم نے صبح کی، اور تیرے نام سے شام کی، تیرے نام سے ہم زندہ ہیں، اور تیرے نام سے مریں گے، اور اُٹھ کر تیری طرف ہی جانا ہے۔“ اور جب شام ہوتی تو آپ صلی اللہ علیہ وسلم فرماتے: ((اللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ)) ”یا اللہ! تیرے نام سے ہم نے شام کی، اور تیرے نام سے صبح کی، تیری توفیق سے زندہ ہیں اور تیرے حکم سے مر جائیں گے اور اُٹھ کر تیری طرف ہی جانا ہے۔“ (ابو داؤد، ترمذی۔ امام ترمذی نے اسے حسن قرار دیا ہے۔)","حسن",{"k":"ابوداؤد (۵۰۶۸)، ترمذی (۳۳۹۱)، ابن ماجہ (۳۸۶۸)، احمد (۸۶۴۹)، وصححہ ابن حبان (۲۳۵۴)۔","e":"یعنی ثابت ہوا ہر چیز نے اللہ کی طرف لوٹنا ہے۔ بندے کی پوری زندگی اللہ کے احکام کے مطابق گزرنی چاہیے۔ اور دین اسلام ایسا کامل دین ہے کہ اس نے زندگی کے تمام شعبوں میں ہماری رہنمائی کی ہے۔ پیدائش سے لے کر موت تک، صبح سے شام تک اور سونے سے بیدار ہونے تک زندگی کا کوئی چھوٹا یا بڑا شعبہ ایسا نہیں جو اسلامی رہنمائی سے محروم ہو۔ صبح و شام دونوں وقت یہ دعاء پڑھنا مستحب بھی ہے اور تجدید ایمان بھی اور اللہ کی قدرت کاملہ کا اعتراف بھی اس لیے ہر مسلمان کو چاہیے کہ ان دعاؤں کا التزام کرے۔","m":"نَحْيَا (علم) لفیف مقرون۔ مضارع جمع متکلم۔ ہم زندہ ہوتے ہیں۔"}],[1453,"سیدنا ابو ہریرہ رضی اللہ عنہ ہی سے روایت ہے کہ سیدنا ابو بکر صدیق رضی اللہ عنہ نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم! مجھے کچھ (دعائیہ) الفاظ کی تلقین فرمائیے۔ جنہیں میں جب صبح ہو تب بھی پڑھوں اور جب شام ہو تب بھی۔ آنحضرت صلی اللہ علیہ وسلم نے فرمایا: ((اللَّهُمَّ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَشَرِّ الشَّيْطَانِ وَشِرْكِهِ)) ”اے اللہ! اے آسمانوں اور زمین کو پیدا کرنے والے! اے پوشیدہ اور ظاہر کو جاننے والے، اے ہر چیز کے پالنہار اور بادشاہ میں گواہی دیتا ہوں کہ تیرے سوا کوئی معبود نہیں، میں تیری پناہ میں آتا ہوں، اپنے نفس کے شر میں، شیطان کے شر سے، اور میرے کسی کام میں اس کے شریک ہونے سے۔“ آپ صلی اللہ علیہ وسلم نے فرمایا: صبح کو، شام کو اور جب آپ اپنے بستر پر جائیں، تو یہ پڑھ لیا کریں۔“ (ابو داؤد، ترمذی۔ امام ترمذی نے فرمایا: یہ حدیث حسن صحیح ہے۔)","حسن صحیح",{"k":"ابوداؤد (۵۰۶۷)، ترمذی (۳۳۹۲)، احمد (۷۹۶۱)، ابن حبان (۲۳۴۹)، مستدرک (۱؍۵۱۳)۔\nبخاری فی الادب المفرد (۱۲۰۲)۔","e":"پیدا کرنا اور حکم دینا صرف اللہ تعالی کے ہاتھ میں ہی ہے اس کا کوئی شریک نہیں۔ بندے کو گمراہ کرنے والی دو چیزیں ہیں ایک نفس انسانی دوسری شر شیطانی۔ لہذا ان دونوں سے اللہ کی پناہ مانگی جائے اور یہ حدیث میں مذکور ذکر ہمیشہ کرے۔ سیدنا صدیق اکبر رضی اللہ عنہ یا رسول اکرم صلی اللہ علیہ وسلم سے ہر وقت اعمال خیر سیکھنے کے خواہش مند رہتے تھے اور رسول کریم صلی اللہ علیہ وسلم بھی اپنے صحابہ کرام رضی اللہ عنہم کی تعلیم و تربیت میں مصروف رہتے تھے۔ چنانچہ رسول اکرم صلی اللہ علیہ وسلم نے صدیق رضی اللہ عنہ یا اللہ کو یہ کلمات تعلیم فرمائے جو بہت اعلی اور جامع کلمات ہیں۔ ہر مسلمان کو یہ کلمات پڑھنے کی عادت بنانی چاہیے۔ ہرم ان کا مطلب ہے۔ اے اللہ کریم! زمین اور آسمان کے بغیر پہلے کسی مثال کے تو نے ہی پیدا کیا ہے۔ اور مخلوق سے جو بھی غائب ہے تو اسے جاننے والا ہے اور حاضر کو بھی جانتا ہے یعنی تو حال، ماضی اور مستقبل کو جانتا ہے۔ یہاں رب سے مراد خالق اور اشیاء کا موجد ہے۔ اور ملیک سے مراد ہے کہ جیسے چاہتا ہے تصرف کرتا ہے۔ آگے فرمایا۔ میں زبان و دل سے اعتراف کرتا ہوں معبود حقیقی تو ہی ہے تیرے سوا جس کی بھی پوجا ہوتی ہے وہ باطل ہے۔ پھر نفس کی شرانگیزیوں سے اللہ تعالی سے پناہ طلب کی گئی ہے۔ کیونکہ نفس برائیوں کا حکم دیتا ہے۔ ﴿وَانَّ النَّفْسَ لَأَمَّارَةٌ بِالسُّوءِ إِلَّا مَا رَحِمَ رَبِّي﴾ (يوسف: ۵۳) بے شک نفس البتہ برائی کا حکم دینے والا ہے مگر جس پر میرا رب رحم کرے۔ اگر اللہ کی مدد نہ ہو تو انسان نفسانی شرارتوں سے محفوظ نہیں رہ سکتا اور شیطان شرک کا شکار کرتا ہے اور شہوات اور شبہات کے ذریعہ شیطان اولاد آدم کو گمراہ کرتا ہے اس لیے اس سے اللہ کی پناہ طلب کی گئی ہے۔"}],[1454,"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ انہوں نے فرمایا: جب شام ہوتی تو نبی صلی اللہ علیہ وسلم فرماتے: ((أَمْسَيْنَا وَأَمْسَى الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ)) ”ہم نے شام کی، اور اللہ کی بادشاہت (میں موجود مخلوقات) نے شام کی۔ اللہ کی تعریف ہے اکیلے اللہ کے سوا کوئی معبود نہیں، اس کا کوئی شریک نہیں۔“ راوی فرماتے ہیں: آپ صلی اللہ علیہ وسلم نے غالباً یہ الفاظ بھی فرمائے تھے: ((لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)) ”بادشاہت اس کی ہے، تعریف اسی کی ہے اور وہ ہر چیز پر قادر ہے۔“ (اس کے بعد فرمایا:) ((رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، رَبِّ أَعُوذُ بِكَ مِنَ الْكَسَلِ، وَسُوءِ الْكِبَرِ، رَبِّ أَعُوذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ، وَعَذَابٍ فِي الْقَبْرِ)) ”اے میرے رب! میں تجھ سے اس رات میں جو کچھ ہے اس کی بھلائی، اور جو اس کے بعد ہے اس کی بھلائی مانگتا ہوں، اور جو کچھ اس رات میں ہے اس کی بُرائی سے اور جو اس کے بعد ہے اس کی بُرائی سے تیری پناہ میں آتا ہوں۔ اے میرے رب! میں تیری پناہ میں آتا ہوں سستی سے اور تکبر کی برائی سے۔ اے میرے رب! میں جہنم میں ہونے والے عذاب سے اور قبر میں ہونے والے عذاب سے تیری پناہ میں آتا ہوں۔“ (اور جب صبح ہوتی تو آنحضرت صلی اللہ علیہ وسلم فرماتے: ((أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ)) ”ہم نے صبح کی، اور اللہ کی بادشاہت... میں موجود مخلوقات... نے صبح کی۔ (آخر تک پوری دعا)“ (مسلم)","",{"k":"مسلم (۲۷۲۳)، احمد (۴۱۹۲)، ترمذی (۳۳۸۷)، ابوداؤد (۵۰۷۱)۔","e":"ان اذکار پر صبح و شام ہمیشگی کی جائے اس سے انسان حاضر ذہن رہتا ہے اور رب کائنات کے سامنے اپنی حاضری محسوس کرتا ہے۔ اور اس میں امید ہدایت و نجات اور دنیا و آخرت کی اذیتوں سے سلامتی ملتی ہے۔ اور اللہ تعالیٰ کی ربوبیت اور الوہیت کا انسان معترف رہتا ہے اور اس دعاء میں اللہ تعالیٰ سے خیر و عافیت کا سوال ہے اور دنیا و آخرت کے نقصان دینے والے کاموں سے بچنے کی درخواست ہے۔ صبح و شام میں تبدیلی اللہ کے حکم سے آتی ہے یہ اللہ کی قدرت کی نشانی ہے۔ اس لیے اس وقت اللہ تعالیٰ سے دعاء کی جائے۔ اور جب بندے کا یہ عقیدہ بن جائے کہ اللہ ہی پناہ دیتا ہے تو وہ باقی سب چیزوں سے بے نیاز ہو جاتا ہے اور پھر اسی کی عبادت کرتا ہے اس کی حمد و ثناء کرتا ہے اور اس کا شکر اداء کرتا ہے اور اللہ تعالیٰ اپنی ذات، صفات اور افعال میں یکتا ہے۔ سستی اور بڑھاپا بندے کو اللہ کے ذکر سے روکتے ہیں اور عبادت و اطاعت میں رکاوٹ بنتے ہیں اس لیے ان سے اللہ کی پناہ طلب کی گئی ہے۔"}],[1455,"حضرت عبد اللہ بن خبیب... یہ لفظ نقطے والی خاء کے ضمہ سے ہے۔ رضی اللہ عنہ سے روایت ہے کہ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: ”صبح شام تین بار ﴿قُلْ هُوَ اللَّهُ أَحَدٌ﴾ اور معوذتین پڑھ لیا کر، تجھے ہر چیز سے کافی ہو جائیں گی۔“ (اسے ابو داؤد اور ترمذی نے روایت کیا۔ اور ترمذی نے فرمایا: یہ حدیث حسن صحیح ہے۔)","حسن صحیح",{"k":"ابوداؤد (۵۰۸۲)، ترمذی (۳۵۷۵)، احمد (۲۲۶۶۴)۔","e":"اس میں یہ بتایا گیا ہے صبح و شام سورت اخلاص اور سورت فلق اور سورت الناس پڑھنا مستحب ہے۔ نبی صلی اللہ علیہ وسلم جب بستر پر لیٹنے کا ارادہ کرتے تو یہ تینوں سورتیں تلاوت کر کے ہاتھوں پر پھونک کر جسم پر جہاں تک ہاتھ پہنچتے وہاں تک پھیرتے تھے۔ اس میں ان تینوں سورتوں کی فضیلت بیان ہوئی ہے اور جو شخص اللہ سے پناہ طلب کرتا ہے تو اللہ تعالیٰ اس کی حفاظت کرتے ہیں۔ سورت اخلاص میں اللہ تعالیٰ نے نہ تو طہارت کے مسائل بیان کئے ہیں۔ نہ نماز کے احکام، نہ تجارت وغیرہ کا ذکر کیا ہے بلکہ صرف اپنے لیے توحید بیان کی ہے اور شرک سے بیزاری بیان کی ہے۔ اور اسے نبی صلی اللہ علیہ وسلم نے قرآن کے تیسرے حصہ کے برابر قرار دیا ہے۔ (بخاری: ۵۰۱۵) اور دونوں قل اس وقت نازل ہوئے تھے جب نبی صلی اللہ علیہ وسلم پر خبیث لبید بن اعصم یہودی نے جادو کیا تھا۔ جبریل علیہ السلام نے آپ صلی اللہ علیہ وسلم پر دم کیا تو جادو اتر گیا۔ (بخاری: ۳۲۶۸) اور نبی صلی اللہ علیہ وسلم نے فرمایا۔ ان دونوں کے ساتھ پناہ پکڑنے والے کی مانند کسی نے پناہ نہیں پکڑی۔ (ابوداؤد: ۱۴۶۳ اسنادہ صحیح) فلق صبح کو کہتے ہیں اور پھر رات سے پناہ مانگی گئی ہے کیونکہ رات میں زہریلے کیڑے مکوڑے، سانپ بچھو وغیرہ اور درندے اپنی جگہوں سے باہر نکلتے ہیں۔ اور جادو کا کام کرنے والے جو جادو کی گرہیں باندھتے ہیں اور اس میں طلسم نقش کرتے ہیں اور شیطانوں سے پناہ مانتے ہیں اور ان سے تعاون طلب کرتے ہیں اور حاسد سے نظر لگانے والا مراد لیتے ہیں۔ اس کی آخری تین آیات پر غور کریں تو بہت ہی خوبصورت مناسبت پائی جاتی ہے۔ وقب رات ہے اس میں بلائیں خفیہ طور پر اترتی ہیں۔ اور سحر (جادو) بھی خفیہ ہوتا ہے اور نظر بد بھی پوشیدہ ہے۔ اور پناہ صبح کے رب کے ساتھ لی گئی ہے جو کہ صبح کو روشن کرتا ہے۔ یعنی ان پوشیدہ نقصان دہ چیزوں سے اجالا کرنے والے رب سے پناہ طلب کی گئی ہے۔ آگے سورت الناس ہے اس میں معبود حقیقی کا کامل غلبہ بتایا گیا ہے کہ اس کی کوئی حکم عدولی نہیں کر سکتا۔ پھر ذکر ہے کہ شیطان وسوسے ڈالتا ہے اور خصوصاً ہمارے دور میں تو اس کی وسوسہ کی فراوانی ہے مال و اولاد کی کثرت ہے اتنی نعمتوں کی ارزانی پہلے نہ تھی لیکن وسوسے اور نفسیاتی بیماریاں عام ہیں۔ نبی صلی اللہ علیہ وسلم نے فرمایا تھا۔ واللہ! مجھے تمہارے فقر کا ڈر نہیں۔ مجھے تو یہ ڈر ہے کہ تم پر دنیا کے در کھل جائیں گے تم اس میں رغبت کرو گے جس طرح تم سے پہلے لوگوں نے کی یہ چیز تمہاری ہلاکت کا باعث ہوگی جیسا کہ تم سے پہلے لوگوں کو اس نے ہلاک کر دیا۔ (بخاری: ۶۴۲۵) خناس اللہ کے ذکر کے وقت چھپ جاتا ہے اس کے علاوہ وسوسے ڈالتا رہتا ہے اور یہ وسوسہ انداز جنوں سے بھی ہیں اور انسانوں سے بھی ہیں۔ جنوں والے وسوسہ انداز انسان کے سامنے آتے ہیں۔ اور خوف زدہ کر دیتے ہیں۔ کئی صورتیں اختیار کرتے ہیں کبھی شیر، کبھی بھیڑ یا کبھی بجھ وغیرہ کی شکل دھارتے ہیں۔ نبی صلی اللہ علیہ وسلم نے ان کا علاج یہ بتایا ہے کہ اس وقت انسان اللہ اکبر کہے۔ (احمد: ۱۴۲۷۵) صحیح لغیرہ اس سے یہ وسوسہ اندازی کرنے والا ختم ہو جائے گا۔ اور انسانوں سے وسوسہ اندازی کرنے والے یہ ہیں سادہ لوح عوام کو باطل مذاہب کی طرف لگاتے ہیں اور دین سے دور کرنے کے لیے اسلام پر اعتراض کرتے ہیں۔ ان میں نجومی، کاہن اور شعبدہ باز بھی شامل ہیں۔ رب تعالیٰ کی ذات پر قرآن پاک کے بارے میں رسول اکرم صلی اللہ علیہ وسلم کے بارے میں، طہارت کے بارے میں، کہ جماعت کا وقت گزر جاتا ہے لیکن اسے وضوء کی تسلی نہیں ہوتی۔ اور نماز میں کہ تکرار ہی ختم نہیں ہوتی اور گھر میں کہ اہل وعیال سے بدگمان ہو جاتا ہے کہ انہوں نے جادو کیا ہے اور طلاق کا خیال ہی ہر معاملہ میں دل میں آیا رہتا ہے یہ سب وسوسہ اندازی شیطان کی ہے۔ نبی صلی اللہ علیہ وسلم نے فرمایا جب تم میں سے کوئی اس قسم کے وسوسے پائے تو اعوذ باللہ من الشیطن الرجیم پڑھے اور ان وسوسوں سے رک جائے۔ (بخاری: ۳۲۷۶) اور یہ آخری دونوں قل پڑھے یہ سب درست ہو جاتا ہے بشرطیکہ یقین اور اخلاص ہو۔","m":"تَكْفِيكَ (ض) ناقص یائی) مضارع معلوم واحد مونث غائب ضمیر مفعول یہ ہے۔ تجھے کفایت کرتا ہے۔","r":"عبد اللہ بن خبیب رضی اللہ عنہ یہ انصار کے حلیف تھے۔ باپ اور بیٹا دونوں شرف صحابیت سے بہرہ ور ہیں۔ ان کا شمار اہل مدینہ میں ہوتا ہے۔ ان سے ان کے دونوں بیٹے روایات بیان کرتے ہیں۔ عبد اللہ بن خبیب رضی اللہ عنہ کے بارے میں وارد ہے یہ سخت تاریک اور بارش والی رات میں رسول اکرم صلی اللہ علیہ وسلم کو تلاش کرنے نکلے تا کہ آپ سے دعائیں کرائیں۔ ان کی ملاقات رسول اکرم صلی اللہ علیہ وسلم سے ہوئی۔ آپ نے کہا۔ بتاؤ۔ انہوں نے دو دفعہ جواب نہ دیا۔ تیسری دفعہ بولے۔ اللہ کے رسول صلی اللہ علیہ وسلم کیا کہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا۔ قل ھو اللہ احد اور معوذتین صبح و شام تین مرتبہ پڑھا کرو۔ اللہ تمہیں ہر چیز سے بچائے گا۔ انہوں نے تین احادیث بیان کی ہیں۔ (رضی اللہ عنہ)"}],[1456,"سیدنا عثمان بن عفان رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جو بھی بندہ ہر دن کی صبح کو، اور ہر رات کی شام کو یہ الفاظ تین بار پڑھ لیتا ہے، اسے کوئی چیز نقصان (یا تکلیف) نہیں دیتی: ((بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ)) ”اللہ کے نام سے، جس کے نام کے ساتھ زمین کی، یا آسمان کی کوئی چیز ضرر نہیں پہنچاتی، اور وہ سننے والا، جاننے والا ہے۔“ (ابو داؤد، ترمذی۔ امام ترمذی نے فرمایا: یہ حدیث حسن صحیح ہے۔)","حسن صحیح",{"k":"ابوداؤد (۵۰۸۸)، ترمذی (۳۳۸۸)، ابن ماجہ (۳۸۶۹)، احمد (۴۷۴)، حاکم (۱؍۵۱۳)، ابن حبان (۲۳۵۲)۔\nبخاری فی الادب المفرد (۶۶۰)۔\nنسائی فی عمل الیوم واللیلہ (۱۵)۔","e":"باسم اللہ یعنی میں اس عزیز و غالب رب کے نام کے ساتھ حفاظت طلب کرتا ہوں جس کے نام گرامی سے جمادات، جانوروں، جنوں، شیطانوں اور عاقل اور غیر عاقل سے حفاظت طلب کی جاتی ہے۔ کیونکہ وہ کائنات کے سارے حالات جانتا ہے اور ان میں کلی تصرف رکھتا ہے اس کے حکم کے بغیر کوئی چیز دم نہیں مارسکتی اس میں انسان کو تاکید کی گئی ہے کہ وہ اس دعاء سے اپنے ایمان کو تازہ کرے۔ اس کے ذریعہ وہ ہر مایوسی اور نقصان سے بچ سکے گا۔ اس میں یہ بتایا گیا ہے کہ نجات اور سلامتی کی طلب تمام مصائب سے عافیت کے لیے اس اللہ وحدہ لاشریک پر اعتماد کیا جائے کیونکہ وہ انسان کا محافظ ہے ہر اذیت اور بلا صرف اسی کی قدرت سے دور ہوتی ہے۔ اس حدیث کے آخر میں ہے کہ سیدنا ابان بن عثمان رضی اللہ عنہ جو اس حدیث کے راوی ہیں انہیں فالج تھا۔ جب بھی تھا انہوں نے یہ حدیث بیان کی تو ان کا شاگرد ان کی طرف تعجب سے دیکھنے لگا (یعنی مقصد اس کا یہ تھا اگر یہ دعاء ہر نقصان سے بچاتی ہے تو پھر بھی آپ کو فالج ہو گیا ہے۔ حالانکہ یہ دعاء آپ پڑھتے تھے) اس کے اس طرح دیکھنے پر انہوں نے کہا۔ دیکھ کیا رہے ہو۔ اللہ کی قسم نہ میں نے نہ ہی سیدنا عثمان رضی اللہ عنہ نے جھوٹ بولا ہے یعنی حدیث صحیح ہے۔ دراصل جو مجھے فالج کی تکلیف ہوئی ہے اس کی وجہ یہ ہے کہ مجھے کسی وجہ سے غصہ آ گیا اور میں یہ دعاء پڑھنا بھول گیا تھا۔ اس عبرت ناک واقعہ سے چند اہم علمی باتیں سامنے آتی ہیں۔ (۱) غصہ بندے اور اس کی عقل کے درمیان حائل ہوتا ہے۔ (۲) جب اللہ تعالیٰ کی قضا و قدر نافذ ہو جائے تو پھر وہاں تدبیر کام نہیں آتی۔ (۳) دعاء سے قضا و قدر ٹل جاتی ہے۔ (۴) حدیث کے راویوں نے احادیث کی امانت کو پوری دیانت اور ایمانداری سے ہم تک پہنچایا ہے۔ (۵) اسلاف کی قوت یقین کا بھی پتہ چلتا ہے کہ انہیں رسول اکرم صلی اللہ علیہ وسلم کے فرمان کی سچائی پر بے حد اعتماد تھا کہ اس پر عمل کر لیتے تو نقصان نہ ہوتا۔"}],[1457,"سیدنا حذیفہ رضی اللہ عنہ اور سیدنا ابو ذر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب اپنے بستر پر تشریف لے جاتے تھے تو فرماتے تھے: ((بِاسْمِكَ اللَّهُمَّ أَحْيَا وَأَمُوتُ)) ”یا اللہ! تیرے ہی نام سے میں زندہ ہوں اور مروں گا۔“ (بخاری)","",{"k":"بخاری (۶۳۱۲)، احمد (۲۳۲۷۱)، ترمذی (۳۴۱۳)، ابوداؤد (۵۰۴۹)۔","e":"مسلمان کے لیے مستحب ہے کہ سونے سے پہلے یہ دعاء پڑھے۔ اس سے رسول اکرم صلی اللہ علیہ وسلم کے اسوہ حسنہ پر عمل ہوگا اور یہ دعاء انسان کو یاد کرا رہی ہے۔ موت کو ہر حال میں سامنے رکھا جائے۔ یہ دعاء پڑھنے سے انسان کے سامنے یہ بات تازہ رہتی ہے کہ یہ زندگی اللہ ہی کی امانت ہے اسی کی مشیت سے میں جی رہا ہوں وہ جب چاہے گا میرا چراغ زندگی گل کر دے گا لہذا زندگی کے یہ ایام مجھے اللہ کی رضا میں گزارنے چاہیے اس کی نافرمانی میں نہیں۔ یہ دعاء باب آداب النوم (۱۲۳۶) میں گزر چکی ہے۔","i":"اللہ تعالیٰ نے فرمایا: ﴿إِنَّ فِي خَلْقِ السَّمَوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِأُولِي الْأَلْبَابِ الَّذِينَ يَذْكُرُونَ اللَّهَ قِيَامًا وَقُعُودًا وَعَلَى جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَوَاتِ وَالْأَرْضِ﴾ (آل عمران: ۱۹۰)،(۱۹۱) ”آسمانوں اور زمین کی تخلیق میں، اور دن رات کے ایک دوسرے کے پیچھے آنے میں عقلوں والوں کے لئے یقیناً نشانیاں ہیں، وہ جو کھڑے ہوں، بیٹھے ہوں، یا پہلوؤں پر (لیٹے ہوئے) ہوں (ہر حال میں) اللہ کا ذکر کرتے ہیں، اور آسمانوں اور زمین کی تخلیق پر غور کرتے ہیں۔“ سورت آل عمران آیت (۱۹۰۔۱۹۱) کی تشریح: سارے بندے اس کے محتاج ہیں۔ مخلوق کا وہ رب ہے۔ ان کی زندگی کی تدبیر وہ کرتا ہے ان کے تمام امور اس کے تصرف میں ہیں۔ وہی رب ہے اس کے سوا کوئی رب نہیں۔ وہی معبود ہے اس کے سوا کوئی معبود نہیں ہاں، یہ وہ سمجھ پائے گا جو صحیح عقل والا ہو اور روشن بصیرت والا ہو۔"}],[1458,"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ان سے اور فاطمہ رضی اللہ عنہما سے فرمایا تھا: ”جب تم اپنے بستروں پر آؤ، یا فرمایا: جب تم اپنے بستروں پر لیٹو تو چونتیس بار اللہ اکبر کہو، تینتیس بار سبحان اللہ کہو، اور تینتیس بار الحمدللہ کہو۔ ایک روایت میں سبحان اللہ چونتیس بار اور ایک روایت میں اللہ اکبر چونتیس بار ہے۔ (یعنی باقی دو الفاظ تینتیس، تینتیس بار ہیں۔) (متفق علیہ)","متفق علیہ",{"k":"بخاری (۶۳۱۸، ۳۱۱۳)، مسلم (۲۷۲۷)، احمد (۱۸۳۸)، ترمذی (۳۴۰۵)، ابوداؤد (۵۰۶۲)۔","e":"اس میں ترغیب ہے کہ سوتے وقت اس ذکر کو ہمیشہ کیا جائے۔ بستر پر پناہ لینے کا مطلب ہے جب تم سونے کے لیے اپنے بستر پر بیٹھو تو یہ اذکار کرو۔ اس کا پس منظر یہ ہے کہ سیدہ فاطمہ رضی اللہ عنہا گھر کا کام کاج کرتیں تو بڑی مشقت اٹھاتیں۔ ایک مرتبہ رسول اکرم صلی اللہ علیہ وسلم کے پاس کچھ غلام آئے تو سیدنا علی بن ابی طالب رضی اللہ عنہ کے کہنے پر سیدہ فاطمہ رضی اللہ عنہا ابا جان سے غلام کا مطالبہ لے کر رسول اکرم صلی اللہ علیہ وسلم کے پاس گئیں تو آپ صلی اللہ علیہ وسلم سے ملاقات نہ ہو سکی۔ آپ صلی اللہ علیہ وسلم خود رات کو ان کے گھر تشریف لائے اور انہیں پڑھنے کے لیے یہ وظیفہ بتایا۔ سیدنا علی بن ابی طالب رضی اللہ عنہ بیان فرماتے ہیں میں نے اسے کبھی پڑھنا نہ چھوڑا تھا۔ ان سے دریافت کیا گیا آپ جنگ صفین میں مصروف تھے اس وقت بھی نہ چھوڑا تھا کہا میں نے صفین کی رات بھی اسے پڑھنا نہ چھوڑا تھا۔ یہ بھی ثابت ہوا یہ وظیفہ کرنے سے کام کاج سے مشقت نہیں ہوتی۔ اور اس واقعہ سے یہ بھی ثابت ہوا کہ عورت پر اپنے خاوند کی خدمت کرنا واجب ہے۔ آج کل کے بعض نام نہاد مفکر میڈیا پر بیان کر رہے ہیں چونکہ ان کا مقصد عورت کو زینت خانہ سے باہر نکال کر رونق محفل اور نذر سیاست کرنا ہوتا ہے یہ کہتے ہیں عورت کے ذمہ خاوند کی دیگر خدمت ضروری نہیں۔ اگر ایسا ہوتا تو جب سیدہ رضی اللہ عنہا نے خادم کا مطالبہ کیا تھا تو آپ یہ وظیفہ نہ بناتے بلکہ کہتے تمہاری کونسی ذمہ داری ہے تم خدمت چھوڑ دو بلکہ خدمت پر برقرار رکھا اور اس کا حل بتا دیا۔ امام ابن تیمیہ رحمہ اللہ فرماتے ہیں۔ جو اس ذکر کو پابندی سے پڑھے گا وہ تھکن سے دو چار نہیں ہوگا کیونکہ سیدہ فاطمہ رضی اللہ عنہا نے تھکاوٹ کا شکوہ کیا تھا اور آپ صلی اللہ علیہ وسلم نے یہ تسبیحات بتائیں۔ ظاہر ہے جو انہیں ہمیشہ پڑھے گا وہ اللہ کے فضل و کرم سے تھکان سے محفوظ رہے گا۔ (فتح الباری: ۲ ص ۲۲۷) ایک بات یہ بھی یاد رہے کہ یہاں تو اللہ اکبر چونتیس دفعہ کہنے کا ذکر ہے بعض روایات میں جو کہ یہاں بھی ہے سبحان اللہ چونتیس مرتبہ کہنے کا لفظ ہے بعض روایات میں الحمد للہ چونتیس مرتبہ آیا ہے مطابقت یہ ہے کہ ان میں سے کسی بھی ذکر کو (۳۴) مرتبہ کر کے سو پورا کیا جائے۔ صحیح احادیث میں یہ وظیفہ نماز فرض کے بعد ذکر کرنے کی بھی ترغیب ہے۔ اور سوتے وقت بھی اسے معمول بنانا سنت سے ثابت ہے۔","m":"أَوَيْتُمَا (ض) مہموز الفاء اور لفیف مقرون۔ ماضی تثنیہ مذکر حاضر۔ تم جگہ پکڑو۔"}],[1459,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب کوئی شخص اپنے بستر پر آئے، تو اپنے تہبند کے اندر والے حصے کے ساتھ اپنا بستر جھاڑ لے، کیونکہ اسے معلوم نہیں، اس کے بعد اس (بستر) پر کیا کچھ آیا ہو (یعنی کیڑے مکوڑے، گرد غبار) پھر کہے: ((بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، إِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا، فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ)) ”اے میرے رب! میں نے تیرے نام سے اپنا پہلو (بستر پر) رکھا، اور تیری توفیق سے اسے اٹھاؤں گا۔ اگر تو میری جان قبض کر لے تو اس پر رحم کرنا، اور اگر تو اسے دوبارہ بھیج دے (اور مجھے بیدار کر دے) تو اس کی حفاظت کرنا، جس چیز کے ساتھ تو اپنے نیک بندوں کی حفاظت فرماتا ہے۔“ (متفق علیہ)","متفق علیہ",{"k":"بخاری (۶۳۲۰)، مسلم (۲۷۱۴)، احمد (۷۸۱۱)، ترمذی (۳۳۹۸)، ابوداؤد (۵۰۵۰)۔","e":"اس میں یہ بھی ہے کہ بستر پر پہلو رکھ کر سونے لگیں تو یہ دعاء پڑھی جائے کیونکہ اس میں خود کو اللہ کی ذات گرامی کے مکمل طور پر سپرد کرنے اور نفسیاتی سکون اور فکری اطمینان کی درخواست ہے۔ اور فوت ہونے کی صورت میں رحمت الہی طلب کی ہے اور دوبارہ اٹھنے کی صورت میں اللہ تعالیٰ کی حفاظت میں رہنے کی دعاء ہے۔ کہ اللہ کریم پوری زندگی مجھے اپنی حفظ و امان میں رکھنا ایک لمحہ بھر بھی مجھے اپنے نفس کے حوالہ نہ کرنا۔"}],[1460,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم جب بستر پر تشریف لے جاتے تھے، تو اپنے ہاتھوں پر پھونک مارتے اور معوذات پڑھتے اور جسم مبارک پر دونوں ہاتھ پھیر لیتے۔“ (متفق علیہ) بخاری اور مسلم کی ایک روایت میں یہ الفاظ ہیں: ہر رات نبی کریم صلی اللہ علیہ وسلم جب بستر پر تشریف رکھتے تو دونوں ہتھیلیاں اکٹھی کر کے ان میں پھونک مارتے اور ان میں ﴿قُلْ هُوَ اللَّهُ أَحَدٌ، وَقُلْ أَعُوذُ بِرَبِّ الْفَلَقِ، وَقُلْ أَعُوذُ بِرَبِّ النَّاسِ﴾ پڑھتے، پھر اپنے جسم پر جہاں تک پھیر سکتے دونوں ہاتھ پھیرتے۔ آپ صلی اللہ علیہ وسلم اپنے سر مبارک اور چہرہ مبارک سے اور جسم مبارک کا جو حصہ سامنے ہے اس سے شروع کرتے۔ آپ صلی اللہ علیہ وسلم تین بار اسی طرح کرتے تھے۔“ (متفق علیہ)","متفق علیہ",{"k":"بخاری (۶۳۱۹)، مسلم (۲۱۹۲)، احمد (۲۴۸۵۳)، ابوداؤد (۳۹۰۲)، ترمذی (۳۳۹۹)۔","e":"اس میں نبی اللہ صلی اللہ علیہ وسلم نے ہمیں تعلیم دی ہے کہ قول و عمل کے ذریعہ سوتے وقت یہ اذکار پڑھ کر سونا مسنون ہے۔ اس میں اللہ کی مکمل پناہ ہے اور ہر ضرر اور نقصان سے نجات ہے۔ اور قرآن مجید کی تاثیر ہے کہ اسے پڑھ کر جسم پر پھونکنے سے انسان شیطان کی شر سے بچ جاتا ہے۔ یہ بھی ثابت ہوا کہ غیر محرم کے علاوہ کسی کے جسم پر ہاتھ پھیر کر دم کرنا زیادہ مفید ہے۔ انتباہ: علامہ عثیمین رحمہ اللہ نے اس حدیث کی تخریج میں کہا ہے۔ ”ہم نے اسے صحیح مسلم میں نہیں پایا۔“ (شرح ریاض: ص ۱۲۵۰) اوپر ہم نے کتاب باب اور رقم تحریر کردی ہے اس پر یہ حدیث صحیح مسلم میں دیکھی جاسکتی ہے۔ (گوندلوی)","m":"اِسْتَطَاعَ (استفعال) اجوف واوی) ماضی واحد مذکر غائب۔ اس نے طاقت رکھی۔"}],[1461,"سیدنا براء بن عازب رضی اللہ عنہما سے روایت ہے کہ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: ”جب تو اپنے بستر پر جائے تو (پہلے) وضو کر، جس طرح تو نماز کے لیے وضو کرتا ہے، پھر اپنے دائیں پہلو پر لیٹ کر (یہ دعا) پڑھ: ((اللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ)) ”یا اللہ! میں نے اپنا آپ تیرے حوالے کیا، اور اپنے معاملات تیرے سپرد کئے، تجھے اپنا پشت پناہ بنا لیا، تیری (رحمت و نعمت) کی رغبت رکھتے ہوئے اور تجھ سے ڈرتے ہوئے تیرے سوا کوئی جائے پناہ نہیں اور تجھ سے بھاگ کر بچنے کی کوئی جگہ نہیں، میں تیری کتاب پر ایمان رکھتا ہوں، جو تو نے نازل کی ہے اور تیرے نبی پر ایمان رکھتا ہوں (جسے تو نے بھیجا ہے)۔ پھر اگر تو فوت ہو گیا، تو تیری موت فطرت (اسلام) پر ہو گی۔ اور یہ دعا سب (اذکار اور دعاؤں) سے بعد میں پڑھنا۔“ (متفق علیہ)","متفق علیہ",{"k":"بخاری (۶۳۱۱)، مسلم (۲۷۱۰)، احمد (۱۸۵۸۸)، ابوداؤد (۵۰۴۶)، ترمذی (۳۳۹۱)۔","e":"أَلْجَأْتُ یعنی تمام امور میں تیری ذات اقدس پر اعتماد کیا ہے۔ رغبت و رہبت یعنی تیرے عذاب کا خوف ہے اور تیرے ثواب کا طمع ہے۔ فطرت سے مراد وہ دین ہے جو شرک سے خالی ہے اور یہ ایک اپنی دعاء ہے جس میں عبودیت اور بندگی کی صداقت اور اللہ کے لیے اطاعت کی خالص جھلک نمایاں ہے۔","m":"فَوَّضْتُ (تفعیل) اجوف یائی۔ ماضی واحد متکلم۔ میں نے سپرد کیا۔ أَلْجَأْتُ (افعال مہموز اللام) ماضی واحد متکلم۔ میں نے پناہ اختیار کی۔"}],[1462,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب اپنے بستر پر تشریف لے جاتے تھے تو فرماتے تھے: ((الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ)) ”اللہ کا شکر ہے جس نے کھانے کو دیا، پینے کو دیا، ہمارے لیے کافی ہو گیا۔ یعنی ہمارے سب کام سنوارے اور ہمیں ٹھکانا دیا کتنے ہی لوگ ہیں، جن کی کفایت کرنے والا، اور جنہیں ٹھکانا دینے والا کوئی نہیں۔“ (مسلم)","",{"k":"مسلم (۲۷۱۵)۔","e":"یہ دعاء سونے سے پہلے پڑھنا مستحب ہے۔ اس دعاء میں بندہ اللہ تعالیٰ کی نعمتیں شمار کرتا ہے تا کہ ان کے شکر سے انعامات میں اضافہ ہو اور ان کی عظمت اس کے دل میں پیدا ہو۔ یعنی اگر اللہ تعالیٰ نہ کھلاتا اور پلاتا تو کوئی بھی مجھے کھلا پلا نہ سکتا تھا۔ جیسا کہ اللہ تعالیٰ کا فرمان ہے: ﴿أَفَرَأَيْتُمْ مَا تَحْرُثُونَ ○ أَنْتُمْ تَزْرَعُونَهُ أَمْ نَحْنُ الزَّارِعُونَ﴾ (واقعہ: ۶۳۔۶۴) بتاؤ تم کھیتی باڑی کرتے ہو یا کیا تم کاشت کرتے ہو یا یہ کاشت ہمارے حکم سے ہوتی ہے اور ہمیں مشقت سے کفایت کی ہے اور اب رات کے وقت آرام کے لیے پناہ دی ہے۔ کتنے ہی لوگ ہیں جن کے پاس نہ تو مشقت سے بچاؤ ہے اور نہ ہی ٹھکانہ ہے۔ جبکہ اللہ نے کفایت بھی کی ہے اور ٹھکانا بھی دے دیا ہے۔ اسی نے سہولتیں مہیا کی ہیں۔ رسول اکرم صلی اللہ علیہ وسلم نے نیند کے وقت کھانے پینے کا ذکر کیا ہے اس کی حکمت یہ ہے کہ بندے کو کھانے پینے کے بعد ہی صحیح نیند آتی ہے اور اللہ ہی بندے کو بعض چیزوں کے شر سے بچاتا ہے اور کھانے پینے کا انتظام فرماتا ہے۔ اور بندے کو چاہیے کہ اپنے سے کم تر لوگوں کو دیکھے تا کہ اللہ کی نعمتوں کی قدر دانی کا جذبہ پیدا ہو۔ اس حدیث کا مقصد یہ آیہ مبارکہ بھی واضح کر رہی ہے: ﴿ذَلِكَ بِأَنَّ اللَّهَ مَوْلَى الَّذِينَ آمَنُوا وَأَنَّ الْكَافِرِينَ لَا مَوْلَى لَهُمْ﴾ (محمد: ۱۱) بے شک اللہ تعالیٰ ایمان والوں کا مولیٰ ہے اور بے شک کافروں کا کوئی مولی نہیں۔","m":"سَقَانَا (ض) ناقص یائی۔ ماضی واحد مذکر غائب ضمیر مفعول یہ ہے۔ اس نے ہمیں پلایا۔ كَفَانَا (ض) ناقص یائی۔ ماضی واحد مذکر غائب ضمیر مفعول یہ ہے۔ اس نے ہمیں کفایت کیا۔ کافی اسی سے اسم فاعل ہے۔ مُؤْوِي (آوی) سے اسم فاعل ہے۔"}],[1463,"سیدنا حذیفہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب سونے کا ارادہ فرماتے تو اپنا دایاں ہاتھ اپنے رخسار مبارک کے نیچے رکھتے، پھر فرماتے: ((اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ)) ”یا اللہ! مجھے اس دن اپنے عذاب سے بچا لیا، جس دن تو اپنے بندوں کو زندہ کرے گا۔“ (ترمذی۔ انہوں نے فرمایا: یہ حدیث حسن ہے۔) (اسے ابو داؤد نے سیدہ حفصہ رضی اللہ عنہا کی روایت سے بیان کیا ہے، ان کی روایت میں ہے کہ آنحضرت صلی اللہ علیہ وسلم یہ دعا تین بار پڑھتے تھے۔)","حسن",{"k":"ترمذی (۳۳۹۸)، ابوداؤد (۵۰۴۵)، احمد (۲۶۴۶۵، ۲۳۲۴۴)، ابن ماجہ (۳۸۷۷)، ابن حبان (۲۳۵۰، ۱۱؍۹۸)۔","e":"اس میں اس دعاء کی فضیلت بیان ہوئی ہے اور اس میں نبی صلی اللہ علیہ وسلم جو اپنے مولیٰ کریم کے سامنے خضوع اختیار کرتے تھے اور اس کی جلالت ذکر جو ہمیشہ آپ نے دل میں بٹھائی ہوئی تھی اس کا تذکرہ بھی ہے۔ اس میں نبی صلی اللہ علیہ وسلم نے امت کو خبر دار کیا ہے کہ عذاب الہی سے بے خوف نہ ہو جائے اور نہ ہی جہالت اور غفلت کا شکار ہو کر شیطانی چالوں میں آئے۔ بلکہ رضائے الہی کے کام کرے دراصل ایمان خوف اور امید دونوں کے درمیان ہے۔ برے عمل سے اللہ کی گرفت کا ڈر ہو اور نیک عمل سے اس کی رضا اور انعام و اکرام کی امید ہو۔ سوتے وقت یہ دعاء پڑھنا ایمان کی تازگی کا باعث ہے اور دائیں بازو پر لیٹنا مستحب ہے۔ اس دعاء میں حشر کا تذکرہ بھی ہے کہ اس دن اللہ تعالیٰ بندوں کو زندہ کرے گا اور ان کے اعمال کا حساب کتاب لے گا۔ انتباہ: علامہ عثیمین رحمہ اللہ والی شرح کے متن میں ابوداؤد والی روایت کی سند کو ضعیف قرار دیا گیا ہے۔ (ص ۱۲۵۰) لیکن ابوداؤد رقم (۵۰۴۵) کی تخریج میں اسے حسن قرار دیا گیا ہے۔ (۴/ ص ۷۷۸ مترجم) ثابت ہوا کہ ابوداؤد والی سند بھی حسن ہے۔ علاوہ ازیں محققین نے دوسری احادیث کی تخریجات میں اسے صحیح قرار دیا ہے۔","m":"قِنِي (ض) لفیف مفروق۔ امر واحد مذکر حاضر۔ نون وقایہ یاء مفعول یہ۔ مجھے بچا۔"}],[1464,"سیدنا نعمان بن بشیر رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”دعا ہی عبادت ہے۔“ (ابو داؤد، ترمذی۔ ترمذی نے فرمایا: یہ حدیث حسن صحیح ہے۔)","حسن صحیح",{"k":"ابوداؤد (۱۴۷۹)، ترمذی (۳۳۷۲)، احمد (۱۸۳۵۲)، الادب المفرد (۷۱۴)، ابن ماجہ (۳۸۲۸)، حاکم (۱؍۴۹۱)، ابن حبان (۲۳۹۶)۔","e":"دعاء ایک حقیقی عبادت ہے وجہ یہ ہے کہ اس میں ہمہ تن توجہ اللہ کی طرف ہوتی ہے۔ اور اللہ کے غیر سے رخ موڑ لیا ہوتا ہے۔ عبادت اسلام میں یہ معنی رکھتی ہے کہ اطاعت شعاری اور تضرع اور اللہ تعالیٰ کے سامنے جھکنے کا نام عبادت ہے۔ اس لیے بندہ اپنے رب کے سامنے عاجزی کرے، اپنی ضرورت اس کے سامنے پیش کرے اور یہ اعتراف کرے کہ مولیٰ کریم تو ہی میرا مددگار ہے اور تو ہی دعاء قبول کرنے پر قادر ہے۔ یہ مانگے آگے اللہ تعالیٰ کی حکمت ہے کہ وہ اسے مطلوبہ چیز عطاء کر دے یا اسے قیامت کے دن جزا دے یا پھر اس کے عوض کوئی آنے والی تکلیف دور کر دے۔ اسے اپنے اللہ پر مکمل اعتماد اور توکل کرنا چاہیے کسی غیر پر اعتماد نہ کرے۔ اصل میں دعاء عاجزی اور فروتنی کرنے اور اللہ کی قدرت و قوت کا اعتراف کرنا ہے۔ یہی عبادت کی روح ہے۔ اللہ تعالیٰ نے بھی دعاء کو عبادت قرار دیا ہے۔ ﴿وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ إِنَّ الَّذِينَ يَسْتَكْبِرُونَ عَنْ عِبَادَتِي سَيَدْخُلُونَ جَهَنَّمَ دَاخِرِينَ﴾ (غافر: ۶۰) تمہارے رب نے کہا مجھ سے دعاء کرو میں قبول کروں گا۔ بے شک جو لوگ میری عبادت سے تکبر کرتے ہیں عن قریب وہ دوزخ میں جائیں گے ذلیل ہو کر۔ اس میں پہلے دعاء کا ذکر ہے آگے فرمایا۔ عَنْ عِبَادَتِي (میری عبادت سے رخ موڑا) یہ نہیں کہا (عن دعائی) میری دعاء سے رخ موڑا۔ قرآن پاک نے دعاء کو عبادت کہا ہے۔ لہذا جب کوئی رب تعالیٰ سے دعاء کرتا ہے تو اس کی دعاء قبول ہو یا نہ قبول ہو اس عبادت کا اسے ثواب ضرور ملتا ہے۔ چند وہ آیات جن میں لفظ دعاء کا ذکر ہے: (۱) سورت آل عمران پارہ (۳) آیت (۳۸)۔ (۲) سورت الزمر پارہ (۲۲) آیت (۸)۔ (۳) سورت فصلت پارہ (۲۴) آیت (۳۳)۔ (۴) سورت الدخان پارہ (۲۵) آیت (۲۲)۔ (۵) سورت القمر پارہ (۲۷) آیت (۱۰)۔","i":"اللہ تعالیٰ نے فرمایا: ﴿وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ﴾ (المومن: ۶۰) ”اور تمہارے رب نے فرمایا ہے مجھ سے دعا کرو، میں تمہاری دعا قبول کروں گا۔“ اور فرمایا: ﴿ادْعُوا رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً إِنَّهُ لَا يُحِبُّ الْمُعْتَدِينَ﴾ (الاعراف: ۵۵) ”اپنے رب سے دعا کرو، عاجزی کے ساتھ، اور چپکے چپکے، یقیناً وہ حد سے بڑھنے والوں کو پسند نہیں کرتا۔“ اور فرمایا: ﴿وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ﴾ (البقرہ: ۱۸۶) ”جب میرے بندے آپ سے میرے بارے میں سوال کریں تو (انہیں بتا دیجئے کہ) میں قریب ہوں۔ دعا کرنے والے کی دعا قبول کرتا ہوں، جب وہ مجھ سے دعا کرے۔“ اور فرمایا: ﴿أَمَّنْ يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ السُّوءَ﴾ (النمل: ۶۲) ”لا چار کی دعا کون قبول کرتا ہے، جب وہ اسے پکارے؟ اور وہ تکلیف دور کر دیتا ہے۔“ (۱)...... سورت غافر آیت (۶۰) کی تشریح: دعاء کی دو قسمیں ہیں: ۱۔ دعائے عبادت ۲۔ دعائے سوال۔ دعائے عبادت یہ ہے کہ انسان اللہ کی عبادت کرے۔ نماز قائم کرے، زکوۃ دے، روزہ رکھے، حج کرے، جہاد کرے، والدین کے ساتھ حسن سلوک کرے، صلہ رحمی کرے۔ یہ سب کچھ اللہ کی رضا کے لیے کرے۔ یہ سب کام دعائے عبادت ہیں۔ دوسری ہے جو دعائے سوال ہے وہ یہ ہے کہ اللہ تعالیٰ سے کسی چیز کا سوال کیا جائے۔ مثلاً اے میرے رب! مجھے بخش دے، مجھ پر رحم کر، مجھے رزق عطاء کر وغیرہ یہ دعاء بھی عبادت ہے۔ حدیث میں آتا ہے دعاء عبادت ہے۔ (ابوداؤد: ۱۴۷۹۔ ترمذی: ۳۲۴۷۔ احمد: ۱۸۳۵۲ اسنادہ صحیح) یہ دعاء اس لیے عبادت ہے کہ اس میں اللہ کی طرف توجہ ہوتی ہے اور انسان اس کے فضل و کرم کا اعتراف کرتا ہے۔ اللہ کا یہ فرمان کہ تمہارا رب کہتا ہے مجھ سے دعاء کرو میں قبول کروں گا۔ یہ وعدہ دونوں دعاؤں کو شامل ہے۔ دعائے عبادت قبول ہونے کا مطلب ہے۔ اللہ ان عبادات کو اپنی بارگاہ میں قبول کرلے اور مسئلہ اور سوال کی دعاء کی قبولیت یہ ہے کہ اللہ بندے کے سوال کے مطابق اسے عطاء کر دیں۔ اگر دعاء میں زیادتی ہو تو قبول نہیں ہوتی۔ زیادتی والی دعاء یہ ہے کہ رب سے حرام چیز مانگے یا کسی گناہ کی دعاء کرے یا ایک چیز ممکن نہیں وہ مانگ لے۔ مثلاً یہ کہے۔ یا اللہ! مجھے نبی بنا دے۔ یا کسی مظلوم پر بددعاء کرے تو قبول نہیں ہوتی۔ اگر کوئی عورت یہ دعاء کرے کہ میرا بیٹا اپنی بیوی سے محبت نہ کرے۔ یہ بھی قبول نہ ہوگی۔ اگر کسی کا بیٹا نیک لوگوں میں بیٹھتا ہے باپ اس کے لیے بددعاء کرے تو یہ قبول نہ ہوگی۔ دعاء کا تجربہ نہ ہو بعض لوگ اس لیے دعاء کرتے ہیں کہ قبول ہوتی ہے یا کہ نہیں ہوتی ایسا نہ کریں آپ کو یقین ہو کہ اللہ ضرور قبول کریں گے۔ شرط یہ ہے کہ حرام سے اجتناب کیا جائے۔ سود، دھوکا، ملاوٹ اور جھوٹ کے ذریعہ مال نہ کمائے۔ حرام خور کی دعاء بھی قبول نہیں ہوتی۔ نبی صلی اللہ علیہ وسلم نے فرمایا، اللہ تعالیٰ اطیب اور پاکیزہ ہیں۔ طیب اور پاکیزہ ہی قبول کرتے ہیں۔ اللہ تعالیٰ نے ایمانداروں کو بھی حلال کھانے کا حکم دیا ہے۔ اسی طرح پیغمبروں کو بھی حلال کھانے کا حکم دیا ہے۔ (بقرہ: ۱۷۲، المومنون: ۵۱) پھر آپ صلی اللہ علیہ وسلم نے ایک آدمی کا ذکر کیا جو لمبا سفر کرتا ہے، پراگندہ حالت ہے غبار آلود ہے آسمان کی طرف ہاتھ پھیلاتا ہے اور کہتا ہے۔ اے رب! اے رب! اس کا کھانا حرام، اس کا پہننا حرام، اس کی غذا حرام، اس کی دعاء کیسے قبول ہو۔ (مسلم: ۲۳۴۶) دعاء کی قبولیت کے تمام اسباب موجود ہونے کے باوجود نبی صلی اللہ علیہ وسلم اس کی دعا کو قبولیت سے دور قرار دیتے ہیں۔ وجہ اس کی حرام کھانا ہے۔ یہ دعاء کی قبولیت میں رکاوٹ ہے۔ (۲)...... سورت اعراف آیت (۵۵) کی تشریح: اس آیہ مبارکہ میں اللہ حکم دیتے ہیں کہ اپنی اخروی و دنیوی ضروریات صرف اپنے رب سے مانگو، اسے نہایت ہی تذلیل اور خشوع سے پکارو، علانیہ اور پوشیدہ پکارو، مگر دعاء میں زیادتی نہ ہو۔ وہ یہ ہے کہ اللہ کے ساتھ غیر کو پکار لیا اور اسباب اختیار نہ کئے یا اللہ کے طریقہ سے ہٹ کر دعاء کی جائے جیسا کہ بندہ کہے میرا بڑھاپا ختم ہو اور جوانی لوٹ آئے، یا جوانی جائے اور میرا بچپن لوٹ آئے۔ (۳)...... سورت البقرہ آیت (۱۸۶) کی تشریح: اس آیہ مبارکہ میں نبی صلی اللہ علیہ وسلم کو خطاب ہے کہ میرے بندے آپ سے میرے متعلق پوچھیں میں قریب ہوں یا دور ہوں تو کہہ دو میں قریب ہوں۔ وجہ یہ ہے کہ اللہ جل شانہ ساتوں آسمانوں سے اوپر ہیں عرش پر ہیں ہر چیز سے بلند ہیں اور ساتھ قریب ہیں لیکن مستوی اپنے عرش پر ہیں۔ ایک مرتبہ نبی صلی اللہ علیہ وسلم نے صحابہ کرام رضی اللہ عنہم سے کہا تھا وہ ذات اقدس جسے پکارتے ہو وہ تم میں سے ایک کی سواری کی گردن کے بھی قریب ہے۔ (مسلم: ۶۸۶۷) لیکن وہ ساتوں آسمانوں کے اوپر ساتوں زمین آسمان اس کی ہتھیلی میں ایک رائی کے دانے کے برابر ہیں۔ وہ ہر چیز کو گھیرے ہوئے ہے۔ پھر فرمایا، میں دعاء کرنے والے کی پکار کو سنتا ہوں۔ جب وہ یہ خیال کرتا ہے کہ میں اس کا محتاج ہوں اور تکلیف صرف وہی دور کرتا ہے تو میں اس کی دعاء قبول کرتا ہوں بشرطیکہ یہ میری ہی عبادت کریں اور میرے ساتھ حقیقی ایمان رکھیں تو میں بہت جلد دعاء کو سنوں گا۔ ان کی رشد و ہدایت اسی میں ہے کہ یہ ایمان اور اخلاص سے اپنے اللہ کو پکارتے رہیں۔ (۴)...... سورت النمل آیت (۶۲) کی تشریح: جیسا کہ ارشاد باری ہے: ﴿وَإِذَا غَشِيَهُمْ مَوْجٌ كَالظُّلَلِ دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّاهُمْ﴾ (لقمان: ۳۲) اور جب انہیں بادلوں کی مانند موج ڈھانپ لیتی ہے تو یہ اللہ کے لیے دین خالص کرتے ہوئے اس کو پکارتے ہیں۔ پھر وہ انہیں نجات دیتا ہے تو یہ نافرمانیاں کرتے ہیں۔ ثابت ہوا اللہ تعالیٰ کافروں میں سے لاچاروں کی دعاء سن کر انہیں بھی موجوں سے نجات دلاتا ہے۔ تو مؤمن کی دعا کو بالا ولی سنے گا۔ غیر اللہ تو کبھی خاص حد تک سنتا ہے کبھی نہیں سنتا اور کبھی قبول کر سکتا ہے کبھی قبول نہیں کر سکتا۔ آدمی غرق ہو رہا ہو، جل رہا ہو، غیر اللہ نہ تو فریاد رسی کر سکتا ہے نہ ہی کبھی بچا سکتا ہے۔ لیکن اگر یہ اللہ تعالیٰ کو پکارے گا تو وہ قبول بھی کرے گا۔ اور مدد بھی کرے گا۔ اس آیہ مبارکہ میں بت پرستوں کی تردید ہے وہ کہتے ہیں۔ یہ ان کی دعاؤں کو قبول کرتے ہیں یہ حقیقت کے خلاف ہے۔ دوسرے تو کہاں رہے۔ رسول اکرم صلی اللہ علیہ وسلم کو بھی اضطراری حالت میں پکارا جائے تو آپ بھی پکار نہیں قبول کرتے۔ ارشاد باری ہے: ﴿وَمَنْ أَضَلُّ مِمَّنْ يَدْعُو مِنْ دُونِ اللَّهِ مَنْ لَا يَسْتَجِيبُ لَهُ إِلَى يَوْمِ الْقِيَامَةِ وَهُمْ عَنْ دُعَائِهِمْ غَافِلُونَ﴾ (احقاف: ۵) اس سے بڑا کون گمراہ ہے جو اللہ کے سوا اسے پکارتا ہے جو قیامت تک اسے جواب نہیں دے سکتا ہے اور وہ ان کی دعاء سے بے خبر ہے۔"}],[1465,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم جامع دعائیں کرنا پسند فرماتے تھے، اور دوسری دعائیں چھوڑ دیتے تھے۔“ (اسے ابو داؤد نے جید سند سے روایت کیا ہے۔)","",{"k":"ابوداؤد (۱۴۸۲)، احمد (۲۵۱۵۱)، ابن حبان (۲۴۱۲)۔","e":"کوشش یہ کی جائے کہ رسول اکرم صلی اللہ علیہ وسلم کے بتائے ہوئے الفاظ میں دعاء کی جائے کیونکہ آپ صلی اللہ علیہ وسلم کو جامع کلمات دیئے گئے ہیں۔ اور وہ الفاظ اللہ تعالیٰ نے آپ صلی اللہ علیہ وسلم کو سکھائے ہیں اور رسول اکرم صلی اللہ علیہ وسلم کی زبان اقدس سے ملے ہیں اس لیے دعاء کے ان الفاظ میں بڑی ہی تاثیر اور برکت ہوتی ہے۔ اور آپ صلی اللہ علیہ وسلم کی بتائی ہوئی دعاؤں میں بڑی حکمتیں اور علوم جمع ہوتے ہیں۔ اس سے یہ بھی ثابت ہوا کہ بہترین کلام وہ ہے جو مختصر اور مدلل ہو۔ اور رسول اکرم صلی اللہ علیہ وسلم کا یہ وصف خاص تھا کہ آپ جامع بات کرتے تھے۔ انسانی زندگی کا کوئی پہلو ایسا نہیں جو آدمی پر طاری ہوتا ہو اور کوئی حال ایسا نہیں جس کے لیے آپ صلی اللہ علیہ وسلم نے دعاء کی تعلیم نہ دی ہو۔ اس لیے مسنون دعاؤں کا التزام کیا جائے۔ انتباہ: چند آیات کی نشاندہی جن میں لفظ دعاء آیا ہے: (۱) سورت انفال پارہ (۹) آیت (۲۴)۔ (۲) سورت الروم پارہ (۲۱) آیت (۲۵)۔ (۳) سورت البقرہ پارہ (۲) آیت (۱۸۶)۔ (۴) سورت یونس پارہ (۱۱) آیت (۱۲)۔ (۵) سورت الزمر پارہ (۲۴) آیت (۴۹)۔","m":"يَسْتَحِبُّ (استفعال) مضاعف) مضارع معلوم واحد مذکر غائب۔ وہ پسند کرتا ہے۔ يَدَعُ (منع) مثال واوی) مضارع معلوم واحد مذکر غائب۔ وہ چھوڑتا ہے۔"}],[1466,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ انہوں نے فرمایا: نبی صلی اللہ علیہ وسلم کی دعا زیادہ تر یہ ہوتی تھی: ((اللَّهُمَّ آتِنَا فِي الدُّنْيَا حَسَنَةً، وَفِي الْآخِرَةِ حَسَنَةً، وَقِنَا عَذَابَ النَّارِ)) ”یا اللہ! ہمیں دنیا میں بھی بھلائی عطا فرما اور آخرت میں بھی بھلائی عطا فرما، اور ہمیں جہنم کے عذاب سے بچا لے۔“ (متفق علیہ) مسلم کی روایت میں یہ الفاظ بھی ہیں: ”سیدنا انس رضی اللہ عنہ جب کوئی دعا کرنا چاہتے تو یہ دعا کرتے۔ اور جب دعائیں کرنا چاہتے تو اُن میں یہ بھی کرتے تھے۔“","متفق علیہ",{"k":"بخاری (۶۳۸۹)، مسلم (۲۶۹۰)، احمد (۱۱۹۸)، ابوداؤد (۱۵۱۹)۔","e":"یہ وہ دعاء ہے جو نبی اکرم صلی اللہ علیہ وسلم ہمیشہ پڑھا کرتے تھے۔ اس میں دنیا اور آخرت کی ہر خیر داخل ہے۔ اس سے ثابت ہوتا ہے کہ صحابہ کرام رضی اللہ عنہم میں یہ اعلیٰ فکر پائی جاتی تھی کہ وہ رسول اکرم صلی اللہ علیہ وسلم کی اتباع کرتے تھے آپ کے اقوال کی بھی اور آپ کے افعال کی بھی اتباع کرتے تھے۔ لہذا ہمیں بھی یہ دعاء کثرت سے کرنی چاہیے اس کے الفاظ مختصر ہیں مگر دنیا و آخرت کی ہر بھلائی اس میں آجاتی ہے اور جہنم سے بچاؤ کی التجاء بھی ہے۔ اسلامی تعلیمات کتنی زیادہ حکمتوں سے معمور ہیں۔ دنیا کو طلب کرنے کی اجازت دی ہے۔ مگر شرط یہ ہے کہ دنیا میں خیر طلب کی جائے۔ ابن کثیر رحمہ اللہ پہلی جلد میں اس کی تفسیر میں فرماتے ہیں: دنیا میں بھلائی عطا فرما کا مطلب ہے دنیا کی تمام بھلائیاں دے اور آخرت کی بھلائی سے مراد سب سے اعلیٰ بھلائی تو جنت ہے۔ اسی وجہ سے طواف کے دوران رکن یمانی اور حجر اسود کے درمیان یہ دعاء پڑھنا مسنون ہے۔ لوگ اپنی خود ساختہ دعائیں پڑھتے ہیں اور ایسی جامع مسنون دعائیں نہیں پڑھتے یہ ان کی محرومی ہے۔ ہاں، یہ مسنون دعائیں پڑھ کر اپنی زبان میں حاجات مانگ لیں تو کوئی حرج نہیں۔ سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اکرم صلی اللہ علیہ وسلم ایک صاحب کی تیمارداری کے لیے تشریف لے گئے وہ بیماری سے بے حد دبلے ہو چکے تھے۔ آپ صلی اللہ علیہ وسلم نے دریافت کیا۔ کیا تم کوئی دعاء کرتے تھے انہوں نے کہا۔ ہاں میں یہ دعاء کرتا ہوں۔ اللہ کریم! مجھے آخرت میں جو سزا دینی ہے وہ دنیا ہی میں دے دے۔ رسول اکرم صلی اللہ علیہ وسلم نے فرمایا۔ سبحان اللہ! تم اتنی طاقت نہیں رکھتے۔ آپ صلی اللہ علیہ وسلم نے انہیں دعاء اللهم اتنا الخ پڑھنے کا حکم دیا تو وہ شفایاب ہو گئے۔ (مسلم: ۲۶۹۰) چند آیات جن میں لفظ دعاء آیا ہے: (۱) سورت انمل پارہ (۲۰) آیت (۶۲)۔ (۲) سورت اعراف پارہ (۹) آیت (۱۸۹)۔ (۳) سورت یونس پارہ (۱۱) آیت (۲۲)۔ (۴) سورت مریم پارہ (۱۲) آیت (۹۱)۔ (۵) سورت الفرقان پارہ (۱۸) آیت (۱۳)۔ (۶) سورت العنکبوت پارہ (۲۱) آیت (۶۵)۔","m":"آتِنَا (افعال) مہموز الفاء اور ناقص یائی) امر واحد مذکر حاضر ضمیر مفعول یہ۔ ہمیں دے۔ وَقِنَا (ض) (لفیف مفروق) امر واحد حاضر ضمیر مفعول یہ۔ اور ہمیں بچا۔"}],[1467,"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم فرمایا کرتے تھے: ((اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى، وَالتُّقَى، وَالْعَفَافَ، وَالْغِنَى)) ”یا اللہ! میں تجھ سے ہدایت، تقویٰ، پاک دامنی اور استغنا کا سوال کرتا ہوں۔“ (مسلم)","",{"k":"مسلم (۲۷۲۱)، احمد (۳۹۹۰)، ترمذی (۳۴۸۴)۔","e":"الهدى، ضلالت کی ضد ہے۔ خیر اور بھلائی کی رہنمائی اور اس پر چلنے کی توفیق کا سوال ہے۔ التقی سے مراد تقویٰ ہے یعنی اللہ تعالیٰ نے جو کرنے کا حکم دیا ہے اسے سر انجام دینا اور جس سے اللہ تعالیٰ نے منع کیا ہے اس سے رک جانا۔ عفاف سے مراد ہے نا فرمانی سے رک جانا، الغنی سے مراد ہے لوگوں کی محتاجی سے مجھے بے پروا کر دے۔ یہ چند کلمات ہیں مگر کوئی مسلمان انہیں اپنائے تو اس کی دنیا و آخرت میں کامیابی یقینی ہے۔ نبی صلی اللہ علیہ وسلم خود یہ دعاء کیا کرتے تھے۔ علامہ عثیمین رحمہ اللہ ان چار جملوں کی بہت ہی خوبصورت وضاحت فرماتے ہیں: الهدی سے مراد مفید علم ہے۔ ہدایت کی دو اقسام ہیں: (۱) ہدایت علم (۲) ہدایت عمل۔ انسان جب اپنے رب سے ہدایت طلب کرتا ہے تو ان دونوں کی ہدایت طلب کرتا ہے۔ یعنی اللہ کریم مجھے علم بھی عطاء کر اور ساتھ عمل کی بھی توفیق دے۔ جیسا کہ سورۃ فاتحہ میں کہتا ہے۔ ﴿اِهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ﴾ (۶) ہمیں سیدھی راہ کی ہدایت دے۔ اگر ہدایت کے اعتبار سے دیکھا جائے تو لوگوں کی چار اقسام بنتی ہیں۔ (۱) جنہیں اللہ تعالیٰ نے علم و عمل سے نوازا ہے۔ (۲) جو علم و عمل سے محروم ہیں۔ (۳) علم تو ہے عمل سے محروم ہیں۔ ۴۔ عمل تو ہے علم نہیں۔ ان میں سے بہترین قسم کے وہ لوگ ہیں جنہیں علم و عمل دیا گیا ہے۔ اس دعاء میں وہ مکمل طور پر شامل ہیں۔ اور جن کے پاس عمل ہے اور بغیر علم کے ہے تو یہ بھی گمراہی کا شکار ہو جاتے ہیں اور دوسروں کو بھی گمراہ کرتے ہیں۔ (۲) التقی ایک جامع لفظ ہے یہ وقایہ بچا یہ ہے۔ (۳) عفاف: یعنی زنا سے عفت اور پاکدامنی مل جائے۔ یعنی ہر قسم کے زنا سے عفت کا سوال ہے۔ زنا نہایت قسم کا فاحشہ گناہ ہے۔ اللہ تعالیٰ فرماتے ہیں۔ ﴿وَلَا تَقْرَبُوا الزِّنَى إِنَّهُ كَانَ فَاحِشَةً وَسَاءَ سَبِيلًا﴾ (اسراء: ۳۲) زنا کے قریب نہ جاؤ۔ بے شک وہ انتہائی بے حیائی ہے۔ اس سے اخلاص، نسب، دل اور دین ہر چیز میں فساد برپا ہو جاتا ہے۔ (۴) غنا: یعنی اللہ! مجھے اتنا عطا کر کہ جو کچھ لوگوں کے پاس ہے مجھے اس سے بے نیاز کر دے۔ یہ علیحدہ بات ہے مال زیادہ ہو یا کم ہو۔ بہت سے لوگوں کو اللہ تعالیٰ اتنا دیتا ہے جو لوگوں کی محتاجی سے بے نیاز کرتا ہے لیکن ان کے دل کنجوس ہوتے ہیں یا وہ فضول خرچ ہوتے ہیں۔ ان کا فقر ختم نہیں ہوتا۔ لہذا یہ دعاء بار بار پڑھی جائے ایک تو سنت کی اتباع کی برکت ہوگی دوسرا دنیا و آخرت کی ساری خیر اس کے دامن میں سمٹ آئے گی۔ (شرح ریاض: ۱۲۵۶) چند آیات کا ذکر جن میں لفظ دعاء مذکور ہے: (۱) سورت الروم پارہ (۲۱) آیت (۳۳)۔ (۲) سورت لقمان پارہ (۲۱) آیت (۳۲)۔ (۳) سورت نوح پارہ (۲۹) آیت (۵)۔ (۴) سورت ابراہیم پارہ (۱۳) آیت (۲۲)۔ (۵) سورت اعراف پارہ (۹) آیت (۱۹۳)۔"}],[1468,"سیدنا طارق بن اشیم رضی اللہ عنہ سے روایت ہے کہ انہوں نے فرمایا: جب کوئی آدمی اسلام قبول کرتا تھا تو نبی صلی اللہ علیہ وسلم اسے نماز سکھاتے تھے۔ پھر اسے تلقین کرتے تھے کہ یہ الفاظ کہا کرے: ((اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَعَافِنِي، وَارْزُقْنِي)) ”یا اللہ! مجھے بخش دے، مجھ پر رحم کر، میری رہنمائی فرما، مجھے عافیت دے اور مجھے رزق دے۔“ (مسلم) مسلم کی ایک روایت میں سیدنا طارق بن اشیم رضی اللہ عنہ سے ہے کہ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم سے یہ ارشاد سنا: جب ایک آدمی آپ کی خدمت میں حاضر ہوا اور کہا: اللہ کے رسول صلی اللہ علیہ وسلم! جب میں اپنے رب سے مانگوں تو کیا کہوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ((اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَعَافِنِي، وَارْزُقْنِي)) ”یا اللہ! مجھے بخش دے، مجھ پر رحم کر، مجھے عافیت دے اور مجھے رزق دے۔ یہ الفاظ تیرے لیے تیری دنیا اور تیری آخرت جمع کر دیں گے۔“","",{"k":"مسلم (۲۶۹۷)، احمد (۱۵۸۷۷، ۱۵۸۸۱)۔","e":"اس سے یہ بھی پتہ چلا کہ رسول اکرم صلی اللہ علیہ وسلم لوگوں کی خیر و بھلائی کی فکر میں رہتے تھے اور بندے کا اپنے گناہوں کا اعتراف اور استغفار اس کے گناہوں کی مغفرت اور اللہ کی رحمت کے حصول کا سبب ہے اور بندے کا سب سے بڑا مقصد ہدایت کی رہنمائی اور اس پر استقامت ہونا چاہیے۔ یہ بھی بتایا گیا ہے بندہ اگر رزق کی کشادگی حاصل کرلے تو وہ معاشی پریشانیوں سے آزاد ہوکر اللہ تعالیٰ کی اطاعت و بندگی میں مصروف ہو جائے اور بندے کو اپنے رب سے دنیا و آخرت کی بھلائیاں طلب کرنی چاہیے۔ علامہ عثیمین رحمہ اللہ نہایت ہی شاندار انداز پر اس کی وضاحت کرتے ہیں: نماز ارکان اسلام میں سے کلمہ کے بعد سب سے اہم رکن ہے۔ اسی وجہ سے نبی صلی اللہ علیہ وسلم جب کوئی مسلمان ہوتا تو اسے نماز کا طریقہ بتاتے اور اسے حکم دیتے کہ نماز میں یہ دعاء پڑھنا شارح کہتا ہے (گوندلوی) اور سیدنا ابن عباس رضی اللہ عنہما سے حدیث آتی ہے کہ نبی صلی اللہ علیہ وسلم یہ دعاء دو سجدوں کے درمیان پڑھتے تھے۔ (ابوداؤد مع عون رقم ۸۵ کتاب الصلاۃ باب الدعاء بین السجدتین) (حسن ہے)۔ اس میں اس کا یہ اضافہ بھی ہے۔ وَاجْبُرْنِي وَارْفَعْنِي۔ میری کمی پوری کر دے اور مجھے بلند کرے۔ سب سے پہلے کہا ہے۔ اے اللہ! مجھے مغفرت دے۔ جب آدمی مسلمان ہوتا ہے تو اللہ تعالیٰ اس کے گناہ خود ہی معاف کر دیتے ہیں۔ ارشاد باری ہے: ﴿قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنْتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ﴾ (انفال: ۳۸) کہہ دو۔ ان لوگوں کے لیے جنہوں نے کفر کیا اگر وہ باز آجائیں گے تو ان کے گزرے گناہ معاف کر دیئے جائیں گے۔ تاہم ہر مسلمان کے لیے بھی ضروری ہے کہ وہ مغفرت طلب کرتا رہے کیونکہ کوئی انسان ایسا نہیں جس سے خطا سرزد نہ ہو۔ ایک حدیث میں آتا ہے خطا کرنے والوں میں سے بہترین وہ ہیں جو توبہ کرتے ہیں۔ ابن ماجہ: ۴۲۵۱۔ البانی رحمہ اللہ نے اسے حسن کہا ہے۔ (۲) فرمایا۔ وَارْحَمْنِي۔ یعنی مجھ پر پوری رحمت کر دے۔ مغفرت طلب کرنے سے برائیوں اور گناہوں اور سزاؤں سے نجات ملتی ہے اور رحمت طلب کرنے میں مطالب کا حصول ہوتا ہے انسان کے امور کی تکمیل تب ہی ہوتی ہے جب اسے پریشانی سے رہائی ملے اور مطلوب تک رسائی ملے۔ (۳) وَاهْدِنِي کی پوری وضاحت اوپر گزر چکی ہے کہ اس سے مراد علم و بیان کی ہدایت اور رشد و رہنمائی کی ہدایت ہے۔ (۴) وَعَافِنِي۔ مراد ہے ہر مرض سے عافیت دے۔ مرض کی دو قسمیں ہیں: ۱۔ دل کی بیماری ۲۔ جسمانی بیماری۔ ارشاد باری ہے: ﴿فِي قُلُوبِهِمْ مَرَضٌ فَزَادَهُمُ اللَّهُ مَرَضًا﴾ (البقرہ: ۱۰) ان کے دلوں میں بیماری ہے پس اللہ نے ان کی بیماری میں اضافہ کر دیا۔ اور جسمانی بیماری یہ ہے کہ بدن کے اعضاء بیمار پڑ جائیں، ان کے لیے اللہ سے عافیت طلب کرنے کا مقصد یہ ہے کہ قلبی اور بدنی دونوں بیماریوں سے عافیت عطاء فرما۔ جب بدنی بیماری پر آدمی صبر کرے تو اس سے اس کے گناہ مٹتے ہیں اور درجات بلند ہوتے ہیں۔ لیکن جب دل میں بیماری آجائے تو دنیا و آخرت برباد ہو جاتی ہے۔ جب دل کو شک کی بیماری لگ جائے شرک اور نفاق کی بیماری لگ جائے یا اللہ کی اتاری ہوئی وحی سے نفرت کی بیماری لگ جائے یا اللہ کے دوستوں سے بغض کی بیماری ہو تو یہ دنیا و آخرت کے خسارہ کا سبب ہے۔ لہذا جب بھی اللہ تعالیٰ سے عافیت طلب کریں تو ذہن میں یہ قلبی اور جسمانی دونوں بیماریوں کو حاضر کر کے عافیت طلب کریں۔ (۵) وَارْزُقْنِي۔ یعنی میرے اللہ مجھے وہ رزق دے ایسا کھانا، پینا، لباس اور رہائش ہو جو بدن کی صحت و سکون کا باعث ہے، اور دل کے رزق سے مراد ہے کہ مجھے مفید علم و عمل سے نواز دے۔ رزق کی بھی دو قسمیں ہیں: ۱۔ وہ رزق جس سے بدن کی نشو و نما ہے۔ اور ایک رزق ہے جس کے ساتھ دل قوت حاصل کرتا ہے۔ جب بھی انسان اللہ تعالیٰ سے رزق طلب کرے تو دل اور بدن دونوں کا رزق مانگے۔ (شرح ریاض: ۱۲۵۷) چند وہ آیات جن میں دعاء کا لفظ ہے۔ (۱) سورت نوح پارہ (۲۹) آیت (۷)۔ (۲) سورت نوح پارہ (۲۹) آیت (۸)۔ (۳) سورت الکہف پارہ (۱۵) آیت (۵۲)۔ (۴) سورت القصص پارہ (۲۰) آیت (۶۴)۔ (۵) سورت یوسف پارہ (۱۳) آیت (۱۰۹)۔","m":"وَاهْدِنِي (ض) ناقص یائی) امر حاضر واحد نون وقایہ۔ یاء مفعول یہ۔ مجھے ہدایت دے۔ وَعَافِنِي (مفاعلہ) ناقص وادی) امر حاضر واحد مذکر نون وقایہ۔ یاء مفعول یہ۔ مجھے عافیت دے۔"}],[1469,"سیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((اللَّهُمَّ مُصَرِّفَ الْقُلُوبِ، صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ)) یا اللہ! اے دلوں کو پھیرنے والے! ہمارے دلوں کو اپنی اطاعت کی طرف پھیر دے۔“ (مسلم)","",{"k":"مسلم (۲۶۵۴)، احمد (۶۵۶۹)۔","e":"مُصَرِّف سے مراد ہے کہ دلوں کی حالت بدلنے والا۔ یعنی اے دلوں کے معاملات کو بدلنے والے ہمارے دلوں کو ہدایت کے بعد ٹیڑھا نہ کرنا بلکہ اپنی اطاعت کی جانب موڑ دینا۔ تو اس حدیث میں یہ دعاء کرنے کا استحباب ثابت ہوا کیونکہ اس میں اطاعت کے کاموں کی ہدایت طلب کی گئی ہے اور اس پر ہمیشگی کی التجاء ہے۔ وجہ یہ ہے کہ انسانوں کے دل اللہ تعالیٰ کی انگلیوں کے درمیان ہیں جس طرح چاہتا ہے انہیں پھیرتا ہے (مسلم: ۶۷۵۰) لہذا بندے کو چاہیے وہ اللہ تعالیٰ سے ہدایت و استقامت طلب کرے اور کجی سے بچنے کی دعاء کرے اگر بندہ اپنے نفس کے سپرد ہو جائے تو یہ اسے برباد کر دے گا۔ بندہ مومن ہمیشہ نجات کی راہوں پر کوشاں رہتا ہے اور ہر لمحہ اللہ سے ہدایت کے دروازوں پر دستک دیتا ہے۔ آدمی کے دل میں خیالات کا دریا بہتا ہے اور اس کا دل ہر وقت موج حوادث کی زد پر رہتا ہے معلوم نہیں کب شیطان دل میں برا خیال ڈال دے اور کب مال و اولاد کی محبت غالب آجائے اور آدمی غلبہ حب مال و اولاد میں کوئی ایسا کام کر بیٹھے جو اللہ اور اس کے رسول صلی اللہ علیہ وسلم کے خلاف ہو۔ اگر اللہ کی توفیق ہو تو تب ہی نقصان سے بچا جاسکتا ہے۔ چند آیات جن میں لفظ دعاء آیا ہے: (۱) سورت الرعد پارہ (۱۳) آیت (۳۷)۔ (۲) سورت جن پارہ (۲۹) آیت (۳۰)۔ (۳) سورت غافر پارہ (۲۴) آیت (۳۱)۔ (۴) سورت غافر پارہ (۲۴) آیت (۳۲)۔ (۵) سورت یونس پارہ (۱۱) آیت (۱۰۶)۔"}],[1470,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”آزمائش کی سختی سے، بدنصیبی لاحق ہونے سے، بری تقدیر سے اور دشمنوں کے خوش ہونے سے اللہ کی پناہ مانگو۔“ (متفق علیہ) ایک روایت میں ہے کہ سفیان بن عینیہ رحمہ اللہ نے فرمایا: مجھے شک ہے کہ ان سے میں ایک لفظ میں نے (غلطی سے) زیادہ کر دیا ہے۔","متفق علیہ",{"k":"بخاری (۶۶۱۶)، مسلم (۲۷۰۷)، احمد (۷۳۵۵)، نسائی (۸؍۲۶۹)۔","e":"جَهْدِ البلاء ۔ مشقت یعنی جو بھی انسان کو شدت اور مصیبت ہوتی ہے اس کی مشقت مال کی قلت ہو اور عیال کی کثرت ہو یہ بھی مشقت ہے۔ درك الشقاء: بدبختی اور تنگی کا آجانا۔ ہلاکت پر بھی بولتے ہیں۔ شَمَاتَةِ الاعداء سے مراد دشمن کا خوش ہونا۔ سُوء القضا سے مراد ہے کہ دین و دنیا کے بارے میں برا فیصلہ ہو۔ مال و اہل میں برا فیصلہ ہو، برے خاتمہ پر بھی بولا جاتا ہے۔ اور اللہ سے پناہ طلب کرنا مستحب ہے اس میں تضرع اور عاجزی پائی جاتی ہے اور ویسے تکلف سے مسجع کلام کی ممانعت ہے لیکن بغیر تکلف اگر کلام ایک وزن پر آجائے تو یہ درست ہے۔ اس میں حدیث کے راویوں کی امانت و دیانت کا بھی ذکر ہے کہ حضرت سفیان بن عینیہ رحمہ اللہ کو جس جملہ پر شک تھا کہ میں نے کچھ اضافہ کیا ہے تو اس کو بیان کر دیا ہے۔ انہیں شماتة الاعداء کے جملہ میں شک تھا کہ یہ اضافہ ہوا ہے۔ لیکن دوسری روایات سے ثابت ہوتا ہے لفظ یہی ہے جس میں انہیں شک ہوا ہے مگر یہ صحیح ہے حدیث کا حصہ ہے اور ثابت ہے۔ صرف سفیان رحمہ اللہ کو شک ہوا تھا۔ یہ مدرج نہیں صرف راوی کو شک ہوا ہے۔ اس کا حل ہم نے بتا دیا ہے شماتة اعداء یہ ہے کہ ہمیں ایسے حوادث سے دوچار نہ کرنا جو المناک ہوں اور دشمن خوش ہو جائے۔ علامہ عثیمین رحمہ اللہ بہت ہی گہری تشریح فرماتے ہیں: بلاء دو قسم کی ہے۔ ایک جسمانی بلاء۔ جیسا کہ بیماریاں ہیں۔ دوسری معنوی بلاء ہے وہ یہ ہے کہ کوئی انسان کے عیب بیان کرنے پر جت جائے اور اس کی خوبیاں بیان نہ کرے یہ بہت سخت آزمائش ہے۔ اور بدنی بلاء مثلاً اعضاء میں درد ہو، پیٹ میں تکلیف ہو، سینہ یا سر میں یا گردن میں تکلیف ہو۔ ایک بلاء کی تیسری قسم بھی کی جاسکتی ہے وہ یہ ہے کہ بڑے بڑے مصائب سے دوچار ہونا پڑے اور اگر خیر اور آرام و راحت اور اطمینان ہے تو درست رہنا اور اگر کوئی آزمائش آجائے تو دین سے پلٹ جانا۔ اور اللہ تعالیٰ کی قضا و قدر پر ناراض ہونا جیسا کہ ارشاد باری ہے۔ ﴿وَمِنَ النَّاسِ مَنْ يَعْبُدُ اللَّهَ عَلَى حَرْفٍ فَإِنْ أَصَابَهُ خَيْرٌ اطْمَأَنَّ بِهِ وَإِنْ أَصَابَتْهُ فِتْنَةٌ انْقَلَبَ عَلَى وَجْهِهِ﴾ (الحج: ۱۱) بعض لوگ کنارہ پر اللہ کی عبادت کرتے ہیں۔ اگر انہیں خیر ملے تو اس کے ساتھ مطمئن ہوتے ہیں اور اگر انہیں فتنہ پہنچے تو وہ چہرے کے بل پلٹ جاتے ہیں۔ اور شقاء، سعادت کی ضد ہے اور سعادت کی راہ نیک عمل سے ملتی ہے۔ اور بدبختی کا سبب برے اعمال ہیں۔ جب شقاء بد بختی سے اللہ کی پناہ طلب کی جائے تو اس میں ضمناً یہ بات آجاتی ہے کہ اللہ کریم مجھے برے عمل سے بچا لیجیے۔ بری قضا کا ایک مطلب یہ ہے کہ کسی معاملے میں غلط فیصلہ نہ کروں۔ دوسرا مطلب ہے کہ اللہ کریم ایسا حکم نہ جاری کرنا جو میں برا سمجھوں۔ انسان کبھی خواہشات کی پیروی کرتا ہے اور جلد بازی سے کام لیتا ہے سوچ بچار بروئے کار نہیں لاتا اور اضطراب کا شکار ہو جاتا ہے۔ یہ بھی بری قضا ہے۔ اللہ عزوجل کبھی انسان کے لیے ایسا فیصلہ کرتے ہیں جو اسے برا لگتا ہے اور غمزدہ ہو جاتا ہے تو اس پر اسے حکم دیا گیا ہے کہ بری قضا سے اللہ تعالیٰ کی پناہ مانگے۔ اور دشمن کی خوشی سے پناہ کے بارے میں ضابطہ یہ ہے کہ جب دوسرا آپ کے کسی غم سے خوش ہو اور آپ کو پہنچنے والی برائی اسے اچھی لگے تو یہ دشمن ہے۔ دشمن کی خوشی یہ ہے جو انسان کو خوش کن بات ملے یا خیر حاصل ہو تو دشمن کو یہ اچھی نہیں لگتی اس سے اور اس کی شر سے صرف اللہ تعالیٰ ہی بچا سکتے ہیں اس لیے دشمن کی اس نقصان والی روش سے اسی اللہ کی پناہ طلب کی جائے۔ (شرح ریاض: ص ۱۲۵۸) (۱) سورت الشعراء پارہ (۱۹) آیت (۲۱۳)۔ (۲) سورت القصص پارہ (۲۰) آیت (۸۸)۔ (۳) سورت فاطر پارہ (۲۲) آیت (۱۸)۔ (۴) سورت الکہف پارہ (۱۵) آیت (۵۷)۔ (۵) سورت اسراء پارہ (۱۰) آیت (۱۱۰)۔","m":"تَعَوَّذُوا (تفعل) (اجوف واوی) امر جمع مذکر حاضر۔ تم پناہ مانگو۔ أَشُكُّ (ن) (مضاعف) مضارع معلوم واحد متکلم۔ میں شک کرتا ہوں۔ زِدْتُ (ض) (اجوف یائی) ماضی واحد متکلم۔ میں نے زیادہ کیا۔"}],[1471,"انہی سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے: ((اللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي هُوَ عِصْمَةُ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي، وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي، وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ، وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ)) ”یا اللہ! میرا دین درست کر دے، جس میں میرے معاملات کی حفاظت ہے، اور میری دنیا ٹھیک کر دے جس میں میری روزی ہے، اور میری آخرت سنوار دے، جہاں مجھے لوٹ کر جانا ہے، اور زندگی کو میرے لیے ہر بھلائی میں اضافے کا باعث بنا دے، اور موت کو میرے لیے ہر برائی (مصیبت، تکلیف، آفت وغیرہ) سے آرام کا ذریعہ بنا دے۔“ (مسلم)","",{"k":"مسلم (۲۷۲۰)۔","e":"عصمت کا لفظی معنی روکنا اور حفاظت کرنا ہے۔ اس کا مطلب یہ ہے کہ میرے تمام امور کی حفاظت کرنا۔ اس میں میری گزران ہے۔ یہ دعاء نبی صلی اللہ علیہ وسلم امت کی تعلیم کے لیے پڑھتے تھے۔ مقصد یہ ہے کہ اے میرے اللہ! میری عمر اپنے پسندیدہ کاموں میں مصروف کر دے اور اپنے ناپسندیدہ کاموں سے مجھے بچا۔ اصل میں اسلام بندے کو تحفظ دیتا ہے اور اسے گناہ اور گمراہی سے بچاتا ہے۔ مسلمان کو زندگی میں اس طرح محنت کرنی چاہیے جیسے اس نے ہمیشہ زندہ رہنا ہے اور آخرت کے لیے ایسے محنت کرنی چاہیے جیسا کہ اس نے کل فوت ہونا ہے۔ اور مسلمان کی جتنی عمر طویل ہو یہ اس کے اعمال خیر کا باعث بنتی ہے۔ اور مؤمن بندہ اپنے رب سے ملاقات کر کے فتنوں اور شرارتوں سے محفوظ رہتا ہے۔ اس میں دنیا کی اصلاح سے مراد یہ ہے کہ آدمی کی ضروریات کی تکمیل ایسے حلال اور طیب رزق سے ہو جو اس کے لیے اللہ تعالیٰ کی اطاعت اور بندگی میں معاون ہو۔ اور معاد (آخرت) کی اصلاح سے مراد یہ ہے کہ اللہ تعالیٰ کی رضا حاصل ہو اور اس کی مغفرت اور رحمت حاصل ہو۔ اس میں یہ بھی بتایا گیا ہے کہ دین آدمی کو دنیا اور آخرت کی تمام ہلاکتوں سے اور نقصانات سے بچاتا ہے اور ہر برائی سے امان عطاء کرتا ہے۔ دین ہی سے آدمی کے اخلاق سنورتے ہیں۔ اور دین سے ہی آدمی آدمی بنتا ہے، دین نہ ہو تو انسان میں اور حیوان میں کوئی فرق نہیں رہتا۔ اسی وجہ سے سب سے پہلے اس دعاء میں دین کی اصلاح کا ذکر ہے۔ اور دین کی اصلاح اخلاص سے اور رسول اکرم صلی اللہ علیہ وسلم کی اتباع سے ہوتی ہے۔ جو اللہ تعالیٰ کے ساتھ شرک کرتا ہے یا نماز ریاء کاری سے پڑھتا ہے۔ صدقہ، روزہ اور قرآن کی تلاوت یا ذکر الہی اور طلب علم یا جہاد وغیرہ ریاء کاری سے کرتا ہے تو یہ سارا عمل غیر صالح ہے۔ کیونکہ حدیث میں آتا ہے اللہ تعالیٰ فرماتے ہیں۔ میں شرکاء سے بے پرواہ ہوں جس نے وہ عمل کیا جس میں اس نے میرے ساتھ شریک ٹھہرایا میں اسے اس کے شرک کے حوالہ کر دیتا ہوں۔ (مسلم: ۷۴۷۵۔ احمد: ۷۹۹۹) ثابت ہوا شرک اور ریاء کاری عمل کو مردود کر دیتی ہے اور بدعتی کا عمل بھی غیر صالح ہے۔ کیونکہ رسول اکرم صلی اللہ علیہ وسلم فرمایا کرتے تھے ہر بدعت گمراہی ہے اور ہر گمراہی آگ کا باعث ہے۔ (نسائی: ۱۵۷۸، صحیح) ثابت ہوا کہ بدعتی غیر شرعی طریقہ سے جو عمل کرتا ہے وہ بھی مردود عمل ہے۔ اگر چہ وہ حد درجہ خشوع و خضوع اور پوری رقت سے کرے اور آبدیدہ ہو کر کرے۔ اس کے بارے میں نبی صلی اللہ علیہ وسلم نے فرمایا ہے۔ جس نے ہمارے اس دین میں نئی بات ایجاد کی جو اس میں نہیں تو یہ بات مردود ہے۔ (بخاری: ۲۶۹۷۔ مسلم: ۴۴۹۲) ظاہر ہے اس میں خالص دین کی شرارتوں اور فتنوں سے حفاظت اور اصلاح قرار دیا گیا ہے اخلاص سے خالی اور شرک و بدعت والا عمل دین میں شامل ہی نہیں تو اس کی اصلاح کی کیا امید ہو سکتی ہے۔ (۲) اس میں بیان ہوا ہے کہ دنیا درست کر دے۔ دنیا میں آدمی موت تک رہتا ہے یہ دار القرار نہیں خواہ کوئی بادشاہ ہے خواہ کوئی گدا ہے، خواہ کوئی مالدار ہے، خواہ کوئی فقیر ہے، خواہ کوئی سردار ہے، خواہ کوئی ماتحت ہے سب دنیا سے کوچ کر رہے ہیں اور قصہ پارینہ بن گئے۔ آج ہم یہ باتیں کرتے ہیں کہ فلاں کے ہاں بچہ پیدا ہوا، فلاں فوت ہوا کل کو ہماری اطلاع پھیلے گی کہ یہ بھی دنیا سے چلا گیا۔ ہم اپنے بڑوں اور دوستوں اور بھائیوں اور آباء و اجداد کی داستانیں دہراتے ہیں مگر ایسے محسوس ہوتا ہے کہ دنیا میں وہ آئے ہی نہیں وہ صرف ایک خواب سا نظر آتے ہیں۔ خواب تھا جو کچھ کہ دیکھا جو سنا افسانہ تھا۔ بہر صورت یہ دنیا گزران ہے لیکن دار القرار نہیں۔ اگر انسان کو اس میں نیک عمل کی توفیق مل جائے تو یہ بڑی سعادت ہے۔ اگر بد عملی اختیار کی جائے تو یہ دنیا و آخرت کی بد بختی ہے۔ اسی وجہ سے آپ صلی اللہ علیہ وسلم نے دنیا کو معاش کہا ہے کہ اسے گزار کر اسے چھوڑ کر جانا ہے۔ (۳) فرمایا، آخرت درست کر دے۔ کیونکہ اس سے راہ فرار نہیں وہاں ضرور لوٹ کر جانا ہے۔ ارشاد باری بھی ہے: ﴿قُلْ إِنَّ الْأَوَّلِينَ وَالْآخِرِينَ لَمَجْمُوعُونَ ○ إِلَى مِيقَاتِ يَوْمٍ مَعْلُومٍ﴾ (الواقعہ: ۴۹۔۵۰) کہہ دو! بے شک پہلے اور بعد والے البتہ مقررہ دن میں وقت پر جمع کئے جائیں گے۔ ان سب کو اللہ تعالیٰ ایک میدان میں جمع کریں گے اور ارشاد باری ہے: ﴿ذَلِكَ يَوْمٌ مَجْمُوعٌ لَهُ النَّاسُ وَذَلِكَ يَوْمٌ مَشْهُودٌ ○ وَمَا نُؤَخِّرُهُ إِلَّا لِأَجَلٍ مَعْدُودٍ﴾ (ہود: ۱۰۳۔۱۰۴) یہ دن ہے جس میں لوگوں کو جمع کیا جائے گا۔ اور یہ دن ہے جو حاضر کیا جائے گا۔ ہم نے اسے صرف گئے ہوئے دن کے لیے مؤخر کیا ہے۔ دنیا کے دنوں کو گنے ہوئے قرار دیا ہے جو گنتے گنتے ہی ختم ہو جائیں گے۔ آخر قیامت کی طرف لوٹنا ہے۔ شاعر نے خوب کہا ہے۔ كُلُّ ابْنِ أُنْثَى وَإِنْ طَالَتْ سَلَامَتُهُ يَوْمًا عَلَى آلَةٍ حَدْبَاءَ مَحْمُولٌ ”ہر عورت کا بیٹا اگر چہ وہ عرصہ دراز بھی سلامت رہے گا تو ایک نہ ایک دن میت والی چارپائی پر ضرور اٹھایا جائے گا۔“ مطلب یہ ہے کہ اگر رشتہ داروں میں فوت ہوں گے تو چارپائی پر اٹھائے جائیں گے اگر جل گئے تو آگ میں فناء ہو جائیں گے، جنگل میں موت آئے گی تو درندوں کا لقمہ بن جائیں گے اگر سمندر میں مرنے تو مچھلیوں کی خوراک بن جائیں گے۔ بہر صورت انجام آخرت میں ہی جاتا ہے اور اس کی اصلاح یہ ہے کہ اللہ تعالیٰ دوزخ کے عذاب سے نجات دے۔ (۴) زندگی خیر بنا دے۔ اس دنیا میں جب انسان کو خیر کی توفیق مل جائے اور روزانہ نیک اعمال میں اضافہ ہو تو یہ اس کے لیے بہت ہی مسرت افزا ہوگا۔ روز قیامت خوش ہو کر کہے گا۔ (الْحَمْدُ لِلَّهِ الَّذِي هَدَانَا لِهَذَا وَمَا كُنَّا لِنَهْتَدِيَ لَوْلَا أَنْ هَدَانَا اللَّهُ) (اعراف: ۴۳) تمام تعریفات اس اللہ کے لیے جس نے ہمیں اس کی ہدایت دی ہم ہدایت نہ پاتے اگر ہمیں اللہ اس کی رہنمائی نہ کرتے۔ تو مومن کا ہر دن نماز میں، تسبیحات میں، قرآن کی تلاوت میں، امر بالمعروف اور نہی عن المنکر میں اور بھائیوں سے خندہ پیشانی سے پیش آنے وغیرہ نیک اعمال میں اضافہ کرتا ہے اور جتنا نیکی والا دن ہو اتنی نیکیاں ترقی کریں گی۔ نبی اکرم صلی اللہ علیہ وسلم نے بھی فرمایا ہے۔ تم میں سے بہترین وہ ہے جس کی عمر دراز ہو اور عمل نیک ہوں۔ (ترمذی: ۲۳۲۹ اسنادہ صحیح) (۵) فرمایا، موت راحت بنا دے الخ۔ موت زندگی ختم ہونے کو کہتے ہیں۔ اس کے باوجود نبی اکرم صلی اللہ علیہ وسلم نے فرمایا موت میرے لیے ہر شر سے راحت بنا دو انسان کو کچھ پتہ نہیں اسے اس دنیا میں کیا پیش آنے والا ہے۔ دنیا میں عمر دراز ہوتی ہے انسان دین میں فساد پیدا کر لیتا ہے اور کبھی عظیم فتنوں کی آماجگاہ بن جاتا ہے۔ یہاں تک پشیمان ہوتا ہے کہ کاش! مجھے میری ماں جنم ہی نہ دیتی، کاش! میں اس سے پہلے مرچکا ہوتا، یہ بڑے بڑے فتنوں کا سامنا کرتا ہے۔ اس صورت میں یہ موت شر سے راحت بن جاتی ہے۔ چند آیات جن میں ”دعاء“ کا لفظ آیا ہے: (۱) سورت الفرقان پارہ (۱۸) آیت (۱۴)۔ (۲) سورت محمد پارہ (۲۶) آیت (۳۵)۔ (۳) سورت المعارج پارہ (۲۹) آیت (۱۷)۔ (۴) سورت الجن پارہ (۲۹) آیت (۱۸)۔ (۵) سورت انعام پارہ (۷) آیت (۴۰)۔"}],[1472,"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: ”کہہ ((اللَّهُمَّ اهْدِنِي وَسَدِّدْنِي)) یا اللہ! مجھے ہدایت دے اور راہ راست پر قائم رکھ۔“ ایک روایت میں ہے: ((اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالسَّدَادَ)) یا اللہ! میں تجھ سے ہدایت اور استقامت کا سوال کرتا ہوں۔“ (مسلم)","",{"k":"مسلم (۲۷۲۵)، احمد (۱۱۶۸)۔","e":"سَدَاد کا معنی استقامت ہے۔ یہ دعاء نہایت ہی جامع ہے اس میں رشد و ہدایت پر استقامت اور توفیق کی دعاء ہے اور اس میں یہ بتایا گیا ہے کہ ایک داعی دین پر لازم ہے کہ وہ اپنے عمل کی درستی اور مضبوطی کی فکر کرے اور سنت کا التزام کرے۔ اور ہر بندہ تمام امور میں اللہ سے مدد طلب کرے اور عمل درست کا مطلب ہے کہ انسان قول و فعل میں اور عقیدہ میں درست ہو اور صواب کی اسے ایسی توفیق ملے کہ پھر گمراہ نہ ہو۔ ارشاد باری ہے: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا ○ يُصْلِحْ لَكُمْ أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ﴾ (احزاب: ۷۰۔۷۱) اے لوگو! جو ایمان لائے ہو اللہ سے ڈرو اور سیدھی بات کرو وہ تمہارے اعمال درست کر دے گا اور تمہاری مغفرت کر دے گا۔ اس میں اللہ تعالیٰ نے دو فوائد بیان کئے ہیں: ۱۔ سیدھی بات کا فائدہ یہ ہے اعمال کی اصلاح ہوگی۔ ۲۔ گناہوں کی مغفرت ہوگی۔ چند وہ آیات جن میں دعاء کا لفظ آیا ہے: (۱) سورت انعام پارہ (۷) آیت (۴۱)۔ (۲) سورت انعام پارہ (۷) آیت (۵۶)۔ (۳) سورت اعراف پارہ (۸) آیت (۳۷)۔ (۴) سورت اعراف پارہ (۹) آیت (۱۹۴)۔ (۵) سورت اعراف پارہ (۹) آیت (۱۹۷)۔ (۶) سورت اسراء پارہ (۱۵) آیت (۲۷)۔ (۷) سورت مریم پارہ (۱۶) آیت (۴۸)۔ (۸) سورت حج پارہ (۱۷) آیت (۷۳)۔","m":"اهْدِنِي (ض) (ناقص یائی) امر واحد حاضر نون وقایہ یاء مفعول بہ۔ مجھے ہدایت دے۔ وَسَدِّدْنِي (تفعیل) (مضاعف) نون وقایہ یاء مفعول بہ امر واحد مذکر حاضر۔ مجھے درست کر دے۔ سداد اس سے مصدر ہے۔"}],[1473,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے: ((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ، وَالْكَسَلِ، وَالْجُبْنِ، وَالْهَرَمِ، وَالْبُخْلِ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ)) ”یا اللہ! میں تیری پناہ میں آتا ہوں لا چاری سے، سستی سے، بزدلی سے، شدید بڑھاپے سے، اور کنجوسی سے، اور میں قبر کے عذاب سے تیری پناہ چاہتا ہوں، اور زندگی اور موت کے فتنے سے تیری پناہ چاہتا ہوں۔“ ایک روایت میں یہ الفاظ ہیں: ((وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ)) ”اور قرض کے بوجھ سے، اور مردوں کے (مجھ پر ظلم کے ذریعے) غالب آنے سے۔“ (مسلم)","",{"k":"مسلم (۵۴۰۶، ۶۳۲۷)، بخاری (۶۸۷۳)، ترمذی (۳۴۸۰)۔","e":"اَلْجُبْنُ ۔ خوف، دل میں کمزوری یہ شجاعت کی ضد ہے۔ اَلْهَرَمُ ۔ بڑی عمر کا ہونا۔ البخل ۔ جو ادا کرنے کا جائز مطالبہ کیا گیا ہو اسے بھی ادا نہ کرنا۔ ضَلَعِ الدَّيْن سے مراد ہے قرض کا بوجھ۔ اور غلبة الرجال سے مراد ہے کہ ظالم لوگوں کا غلبہ ہے۔ اس میں ان مذکورہ چیزوں سے نجات کے لیے اللہ کی پناہ میں آنے کا ذکر ہے۔ اور آگاہ کیا گیا ہے کہ ان میں خود مبتلا نہ ہونا۔ بندہ سے نیکی کی توقع دو وجہ سے ہوتی ہے۔ مال سے یا جسم و جان سے اور اس نیکی میں دو رکاوٹیں ہیں۔ بخل اور سستی اور کمزوری اس لیے رسول اکرم صلی اللہ علیہ وسلم نے ان سے اللہ کی پناہ مانگی ہے۔ قرض کے غلبہ سے عقل و دانش قائم نہیں رہتی اور لوگوں کے تسلط سے عزت ختم ہو جاتی ہے۔ اس لیے ان سے بھی اللہ کی پناہ مانگی ہے۔ آدمی میں عاجزی اور سستی پیدا ہو جانے کے باوجود جسمانی قدرت و صلاحیت کے کارخیر سے رہ جائے اور عمل صالح کی انجام دہی نہ کر سکے۔ اور اصلاح احوال کو آج کل پر ٹالتا رہے اور اپنی زندگی کی قیمتی لمحات کو آرام طلبی اور کاہلی کی نذر کر دے، بزدلی ایک مذموم صفت ہے انسان عزائم امور اور بڑے بڑے کام انجام دینے سے رہ جاتا ہے۔ اور بے ہمتی شاہراہ عظیم پر طویل سفر طے کرنے سے مانع بن جاتی ہے۔ ظاہر ہے کہ اس سے اللہ کی پناہ مانگنی چاہیے۔ بڑھاپا جس میں آدمی عقل رفتہ اور بے کار محض ہو کر رہ جائے نہ عقل و حواس کا ساتھ دیتے اور نہ اعضاء کام کے قابل نہیں اسی کو قرآن کریم نے ارزل عمر کہا ہے۔ عذاب قبر سے زندگی کے فتنے اور موت کے فتنے سے بھی پناہ مانگنے کی تعلیم دی گئی جس قدر آدمی اللہ کے دین سے دور ہوگا اسی قدر زندگی کے فتنوں میں گرفتار ہوگا۔ اور جس قدر معاصی کی کثرت ہوگی اتنا ہی عذاب قبر کی ابتلاء و آزمائش شدید ہوگی۔ آدمی قرض تلے دب جائے نہ ادائیگی کی قدرت ہو نہ قرض خواہوں سے بھاگ نکلنے کا راستہ ہو آدمی لوگوں کے سامنے اس قدر مقہور اور ذلیل ہو جائے کہ وہ اس پر ظالم بن کر مسلط ہو جائیں اور اس میں نہ مدافعت کی قدرت ہو اور نہ ظلم سہنے کی ہمت۔ اس لیے نبی اکرم صلی اللہ علیہ وسلم نے امت کو ان امور سے اللہ کی بارگاہ میں پناہ کا درس دیا ہے۔ علامہ ہلالی فرماتے ہیں۔ دوسری روایت کا اضافہ ((وَضَلَعَ الدَّيْنِ وَ قَهْرِ الرِّجَالِ)) کے الفاظ کے بارے میں امام نووی رحمہ اللہ کو وہم ہوا ہے۔ یہ مسلم میں نہیں یہ بخاری میں ہیں۔ (بہجة الناظرين: ۲/ ص ۳۵۵) اس کی تائید علامہ ارناءوط رحمہ اللہ نے بھی کی ہے۔ (تحقیق ریاض الصالحین: ص ۴۳۲)"}],[1474,"سیدنا ابوبکر صدیق رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کی: مجھے کوئی دعا سکھا دیجئے جو میں نماز میں مانگا کروں۔ آنحضرت صلی اللہ علیہ وسلم نے فرمایا: کہئے: ((اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ)) ”یا اللہ! میں نے اپنی جان پر بہت زیادہ ظلم کیا ہے اور تیرے سوا کوئی گناہ معاف نہیں کرتا، مجھے اپنے پاس سے مغفرت عطا فرما، بے شک تو ہی بہت مغفرت والا، بہت رحم کرنے والا ہے۔“ (متفق علیہ) ایک روایت میں ہے: ((فی بیتی)) جو دعا میں اپنے گھر میں نماز میں مانگا کروں۔ ”ظُلْمًا كَثِيرًا“ کا لفظ تین نقطوں والی ثاء سے کثیرًا بھی روایت کیا گیا ہے۔ اور ایک نقطے والی باء سے کبیرًا بھی، مناسب ہے کہ دونوں الفاظ پڑھ لئے جائیں اور کہا جائے: کثیرًا کبیرًا (میں نے بہت زیادہ اور بڑا ظلم کیا ہے۔)","متفق علیہ",{"k":"بخاری (۶۳۲۶)، مسلم (۲۷۰۵)، احمد (۸)، ترمذی (۳۵۲۱)، نسائی (۳؍۵۳)۔","e":"اس سے یہ ثابت ہوا کہ یہ دعاء جو نبی اکرم صلی اللہ علیہ وسلم نے جناب سیدنا صدیق اکبر رضی اللہ عنہ کو سکھائی تھی اسے گھر میں اور تشہد کے آخر میں نماز میں پڑھنا مستحب ہے۔ دراصل انسان خطا کا پتلا ہے یہ جس مقام اعلیٰ تک بھی پہنچ جائے اس سے غلطی کا امکان ہے۔ اس لیے اسے ہمیشہ اللہ تعالیٰ سے مغفرت طلب کرتے رہنا چاہیے۔ اور گناہ کا اعتراف و اقرار کر کے انسان کو توبہ کا موقع ملتا ہے اور توبہ سے مغفرت کا دروازہ کھلتا ہے۔ اور علم دین حاصل کرنے کے لیے کسی عالم سے رابطہ کیا جائے جیسا کہ جناب صدیق رضی اللہ عنہ نے رسول اکرم صلی اللہ علیہ وسلم سے دعاء سیکھنے کے لیے درخواست کی۔ اس میں یہ غور کریں سائل جناب صدیق اکبر ہی لیے ہیں۔ اور آپ صلی اللہ علیہ وسلم کو یہ ساری امت سے زیادہ پیارے تھے۔ ظاہر ہے ایک پیارا اپنے پیارے سے سوال کرتا ہے۔ تو اسے جواب کتنے ہی خوبصورت انداز میں دیا ہوگا۔ اس دعاء میں بندے کا اعتراف گناہ کرنا اور ظلم کا اقرار کرنا یہ دعاء کے وسائل میں شامل ہے کہ انسان اپنا حال اپنے رب کے سامنے پیش کرتا ہے۔ جیسا کہ موسیٰ علیہ السلام نے دعاء میں کہا تھا۔ ﴿رَبِّ إِنِّي لِمَا أَنْزَلْتَ إِلَيَّ مِنْ خَيْرٍ فَقِيرٌ﴾ (القصص: ۲۴) اے میرے رب! اس کے لیے جو تو نے مجھے اتارا ہے بھلائی ہے میں تیرا محتاج ہوں۔ اس میں انہوں نے اللہ کے سامنے اپنی حالت کو دعاء کا ذریعہ بنایا ہے۔ اور اس جملہ میں بھی اللہ کی ثناء ہے۔ ”کہ گناہ صرف تو ہی بخشتا ہے“ اس میں اللہ رب العزت کی تعریف ہے اور بندے کا اعتراف نیاز ہے۔ اللہ تعالیٰ خود بھی فرماتے ہیں۔ ﴿وَمَنْ يَغْفِرُ الذُّنُوبَ إِلَّا اللَّهُ﴾ (آل عمران: ۱۳۵) اور گناہ صرف اللہ ہی بخشتا ہے۔ بھائیو! ساری کائنات کے لوگ بھی اکٹھے ہو جائیں تو ایک گناہ بھی معاف نہیں کر سکتے صرف وہ اللہ ہے جو سارے گناہ معاف کر سکتا ہے۔ اور یہ جملہ یہ نسبت اس وجہ سے ہے کہ اللہ کی ذات گرامی جتنی بڑی ہے اتنی ہی اس کی مغفرت بڑی ہے۔ آخر میں غفور اور رحیم دونوں صفات الہی انتہائی مناسب ہیں کہ انسان ان دو صفتوں کو ذریعہ بناتا ہے کہ میں مغفرت تجھ ہی سے اس لیے طلب کر رہا ہوں کہ تو غفور اور رحیم ہے۔"}],[1475,"سیدنا ابوموسیٰ رضی اللہ عنہ سے روایت ہے کہ انہوں نے نبی صلی اللہ علیہ وسلم سے بیان فرمایا کہ آنحضرت صلی اللہ علیہ وسلم یہ دعا کیا کرتے تھے: ((اللَّهُمَّ اغْفِرْ لِي خَطِيئَتِي وَجَهْلِي، وَإِسْرَافِي فِي أَمْرِي، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، اللَّهُمَّ اغْفِرْ لِي جِدِّي وَهَزْلِي، وَخَطَئِي وَعَمْدِي، وَكُلُّ ذَلِكَ عِنْدِي، اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ الْمُقَدِّمُ، وَأَنْتَ الْمُؤَخِّرُ، وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)) ”یا اللہ! میری غلطی اور میری نادانی معاف کر دے، میرا اپنے معاملات میں حد سے بڑھنا بھی معاف کر دے، اور وہ گناہ بھی جنہیں تو مجھ سے زیادہ جانتا ہے، یا اللہ! میرے قصد سے کئے ہوئے، مذاق سے کئے ہوئے، غلطی سے ہو جانے والے، جان بوجھ کر کئے ہوئے گناہ معاف کر دے، اور یہ سب میرے پاس موجود ہیں۔ یا اللہ! مجھے بخش دے جو گناہ میں نے پہلے کئے، جو بعد میں کئے۔ جو چھپ کر کئے۔ جو علانیہ کئے اور جنہیں تو مجھ سے زیادہ جانتا ہے۔ تو ہی آگے بڑھانے والا ہے، تو ہی پیچھے کرنے والا ہے، اور تو ہر چیز پر قادر ہے۔“ (متفق علیہ)","متفق علیہ",{"k":"بخاری (۶۳۹۸)، مسلم (۲۷۱۹)، احمد (۱۹۴۸۹)۔","e":"اس سے معلوم ہوا کہ نبی صلی اللہ علیہ وسلم نے اپنی امت کو جامع دعائیں سکھائی ہیں۔ اس میں نبی صلی اللہ علیہ وسلم کی قول و عمل میں تواضع بھی نمایاں ہوتی ہے۔ اس میں ہر حالت میں اور ہر وقت ہر گناہ سے طلب مغفرت کی ترغیب ہے۔","m":"اِسْرَافِي (افعال) (صحیح) مصدر۔ یاء مضاف الیہ۔ حد سے تجاوز کرنا۔ كُلُّ ذَلِكَ ۔ جو بھی میرے مذکور معاملات ہیں یہ سب میری طرف سے وقوع پذیر ہوئے ہیں۔ اَسْرَرْتُ (افعال) (مضاعف) ماضی واحد متکلم۔ میں نے پوشیدہ کیا۔ الْمُقَدِّمُ (تفعیل) (صحیح) اسم فاعل۔ آگے کرنے والا۔ یعنی جسے چاہے جنت میں پہلے داخل کر دے۔ الْمُؤَخِّرُ (تفعیل) مہموز الفاء اسم فاعل یعنی دوزخ کی جانب جسے چاہے مؤخر کر دے۔"}],[1476,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم اپنی دعاؤں میں یہ بھی فرمایا کرتے تھے: ((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ)) ”یا اللہ! میں تیری پناہ میں آتا ہوں اس عمل کے شر سے جو میں نے کیا اور اس عمل کے شر سے جو میں نے نہیں کیا۔“ (مسلم)","",{"k":"مسلم (۲۷۱۶)، احمد (۲۴۶۸۴)، ابوداؤد (۱۵۵۰)، نسائی (۳؍۵۶)۔","e":"اس میں ترغیب ہے کہ جو گناہ سرزد ہو چکے ہیں اور جن کے وقوع کا امکان ہے ان سب سے اللہ کی پناہ طلب کی جائے اس میں اللہ کی بندگی کی صداقت جھلکتی ہے اور خود پسندی اور تکبر سے دوری پیدا ہوتی ہے۔ مقصد حدیث یہ ہے کہ ہر وہ کام جس کا نتیجہ اللہ کی مشیت میں اچھا نہ ہو اس سے بھی اللہ سے مغفرت طلب کرنی چاہیے۔ ایک مطلب یہ بھی ہے کہ میں اللہ کی پناہ مانگتا ہوں ہر اس کام سے جس کے نتیجے میں دنیا یا آخرت کی سزا در پیش ہو با وجود یہ کہ میں نے اس کا ارادہ نہ کیا ہو۔ اور ان تمام کاموں کے شر سے جو آئندہ واقع ہونے والے ہیں میں تیری پناہ میں آتا ہوں۔ انسان کبھی اچھا عمل کرتا ہے کبھی اس میں خود پسندی اور ریاء کاری آجاتی ہے اس سے اللہ کی پناہ طلب کی ہے۔ نبی صلی اللہ علیہ وسلم اپنے رب کے حق کے بارے میں بہت فکر مند رہتے تھے۔ اور یہ بھی ثابت ہوا کہ بندے کو اپنے عمل پر اترانا نہیں چاہیے بلکہ ہر وقت استغفار کرتا رہے اور نیک عمل کرتا رہے اور اس کی رحمت کی امید رکھے مؤمن کی شان ہی یہ ہے کہ وہ خوف اور امید کے درمیان رہتا ہے۔"}],[1477,"سیدنا عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کی ایک دعا یہ بھی تھی: ((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحَوُّلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ، وَجَمِيعِ سَخَطِكَ)) ”یا اللہ! میں تیری پناہ میں آتا ہوں تیری نعمت ختم ہو جانے سے، تیری عافیت کے چلے جانے سے، تیری اچانک آجانے والی سزا سے، اور تیری ہر ناراضی سے۔“ (مسلم)","",{"k":"مسلم (۲۷۳۹)، ابوداؤد (۱۵۴۵)۔","e":"اس میں ترغیب ہے کہ نعمت کے زوال سے اور عافیت کی تبدیلی سے اور اچانک سزا سے اور اللہ کے غضب کے تمام اسباب سے اللہ کی پناہ طلب کرنا مستحب ہے اور اس میں یہ ترغیب بھی ہے کہ اللہ کی نعمتوں اور عافیت کو رضائے الہی کے کاموں میں استعمال کیا جائے۔ اللہ تعالیٰ نے انسان کو بے شمار نعمتوں سے نوازا ہے۔ ان نعمتوں کی قدر و قیمت کا اندازہ اس وقت ہوتا ہے جب ان میں سے کوئی نعمت زائل ہو جائے، کسی کی اگر بینائی جاتی رہے تو وہ خوب اچھی طرح جان لیتا ہے کہ بینائی کی کس قدر ضرورت ہے۔ اور اس کی اس زندگی میں کس قدر اہمیت ہے۔ غرض ہر نعمت کی قدر و قیمت کا شعور و احساس اس کے زائل ہونے کے بعد ہوتا ہے۔ اس لیے تعلیم فرمائی کہ اللہ جس قدر بھی آپ نے نعمتیں عطاء فرمائی ہیں ان سب کو باقی رکھے، اور ان میں سے کسی سے ہمیں محروم نہ فرما۔ ہمیں عافیت عطاء فرما اور اس صحت و زندگی اور جان و مال کی اس عافیت کو اس وقت تک باقی رکھ جب تک ہم اس دنیا میں موجود ہیں۔ اے اللہ! میں تیری پناہ میں آتا ہوں کہ کسی وقت عافیت پلٹ جائے اور ہم مصیبت میں مبتلا ہو جائیں اور گرداب بلا ہمیں اپنی لپیٹ میں لے لے، اور ناگہانی اور غیر متوقع آفت میں گھر جائیں ہم تیری پناہ میں آتے ہیں ہر طرح کی ناراضی سے تو ہمیں اپنے غضب سے بچا اور ہمیں اپنے حفظ و امان میں لے لے۔ اس سے یہ بھی ثابت ہوا کہ ہر ایسے کام سے بچنا اور دور رہنا چاہیے جو اللہ کو ناراض کرنے والا ہو۔ اور اللہ تعالیٰ کی نعمتوں کا شکر ادا کیا جائے اس سے نعمتوں میں اضافہ ہوتا ہے۔ اور ناشکری سے نعمتوں میں زوال آتا ہے۔ نعمت کلی طور پر چھن جائے یا جزوی طور پر، ہر حالت میں بری حالت سے اللہ کی پناہ مانگی جائے، اور نعمت کا اچانک چھن جانا بتدریج چھن جانے سے زیادہ شدید ہوتا ہے۔ اور سب کچھ اچانک چھن جائے تو یہ اللہ کی ناراضی کا باعث ہے۔ بتدریج چھن جانے میں تنبیہ ہوتی ہے کہ ٹھیک ہو جاؤ۔ اور اپنے اللہ سے رابطہ میں مضبوط ہو جاؤ۔","m":"تَحَوُّلِ (تفعل) (اجوف واوی) مصدر۔ بدل جانا۔"}],[1478,"سیدنا زید بن ارقم رضی اللہ عنہ سے روایت ہے کہ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم یہ دعا فرمایا کرتے تھے: ((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْهَرَمِ، وَعَذَابِ الْقَبْرِ، اللَّهُمَّ آتِ نَفْسِي تَقْوَاهَا، وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا، أَنْتَ وَلِيُّهَا وَمَوْلَاهَا، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ، وَمِنْ قَلْبٍ لَا يَخْشَعُ، وَمِنْ نَفْسٍ لَا تَشْبَعُ، وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا)) ”یا اللہ! میں تیری پناہ میں آتا ہوں لاچاری سے، سستی سے، کنجوسی سے، شدید بڑھاپے سے، اور قبر کے عذاب سے، یا اللہ! میری جان کو تقویٰ نصیب فرما، اسے پاک کر دے، تو اسے سب سے بہتر پاک کرنے والا ہے، تو اس کا مددگار اور مالک ہے۔ یا اللہ! میں تیری پناہ میں آتا ہوں اس علم سے جو فائدہ نہ دے، اس دل سے جو خشوع اختیار نہ کرے، اس دل سے جو سیر نہ ہو، اور اس دعا سے جو قبول نہ ہو۔“ (مسلم)","",{"k":"مسلم (۲۷۲۲)، احمد (۱۹۳۰۸)، ترمذی (۳۵۶۷)۔","e":"”میرے نفس کو تقویٰ دے“ کا مطلب ہے کہ اسے ایسی قوت عطاء کر کہ تیرے احکام کی پیروی کرے اور خواہشات کی اتباع سے دور رہے اور فسق و فجور کے ارتکاب سے بچا رہے اور ”اسے پاک کر دے“ کا مطلب ہے کہ اسے ذلیل اور رذیل حرکات سے محفوظ کر دے۔ تو اس کا ولی ہے یعنی مددگار ہے اور مولیٰ ہے یعنی مالک و آقا ہے۔ اور نفع نہ دینے والے علم سے پناہ یہ ہے کہ ایسا علم جس پر عمل نہ ہو۔ اور خشوع نہ کرنے والے سے پناہ یہ ہے کہ وہ دل رب ذوالجلال کے سامنے جھکتا نہیں سخت دل، لا تشبع وہ دل ہے جو حرص و آز میں ہی غرق رہے سیر نہ ہو۔ ثابت ہوا کہ حدیث میں مذکور معاملات سے اللہ کی پناہ طلب کرنا مستحب ہے۔ اور اس میں تقویٰ اختیار کرنے کی ترغیب ہے اور علم و عمل پھیلانے کی تلقین ہے۔ اور بتایا گیا ہے کہ مومن کو تقویٰ کا التزام کرنا چاہیے اور اطاعت کے کاموں میں کمر بستہ رہنا چاہیے۔ اور دل کو خیر کی قبولیت کے لیے صاف رکھا جائے اور نیک عمل میں اللہ تعالیٰ کی نصرت اور توفیق پر بھروسہ کرے۔ اور وہ علم جو دین اور دنیا کے لیے مفید ہے اسے حاصل کرے جو بے فائدہ ہے اسے حاصل نہ کرے۔ اور قناعت پسندی پیدا کی جائے۔ ڈرنے والا دل وہ ہے جو اللہ تعالیٰ کے ذکر پر مضطرب ہو کر تڑپ جائے اور خوفزدہ ہو جائے اور اللہ کی طرف جھک جائے اور انسان اپنی دعاء کی قبولیت کی شرائط پوری کرے یعنی دعاء میں اخلاص ہو، اور بھلائی طلب کرنے کی دعاء ہو شر کی نہ ہو۔ یقین سے اور حاضر دل ہو کر دعاء کی جائے اور روزی حلال ہو۔ اگر ان میں سے کسی شرط میں کمی ہے تو اسے دور کیا جائے۔","m":"آتِ (افعال) (مہموز الفاء اور ناقص یائی) امر واحد مذکر حاضر۔ دے۔ وَزَكِّهَا (تفعیل) (ناقص واوی) امر حاضر واحد مذکر ضمیر مفعول بہ ہے۔ اور اس کو پاک کر دے۔ لَا يُسْتَجَابُ (استفعال) (اجوف واوی) مضارع مجهول منفی واحد مذکر غائب۔ وہ قبول نہیں کیا جاتا۔"}],[1479,"سیدنا عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم (یہ دعا) فرمایا کرتے تھے: ((اللَّهُمَّ لَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ، وَإِلَيْكَ حَاكَمْتُ، فَاغْفِرْ لِي مَا قَدَّمْتُ، وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ، وَمَا أَعْلَنْتُ، أَنْتَ الْمُقَدِّمُ، وَأَنْتَ الْمُؤَخِّرُ، لَا إِلَهَ إِلَّا أَنْتَ)) ”یا اللہ! میں صرف تیرا مطیع ہوا، تجھی پر ایمان لایا تجھی پر بھروسا کیا، تیری ہی طرف رجوع کیا، تیری مدد سے جھگڑا کیا اور تجھی سے فیصلہ چاہا، میرے وہ گناہ معاف کر دے جو میں نے پہلے کئے جو بعد میں کئے، جو چھپ کر کئے اور جو علانیہ کیے تو ہی آگے بڑھانے والا ہے اور تو ہی پیچھے ہٹانے والا ہے، تیرے سوا کوئی معبود نہیں۔“ بعض راویوں نے یہ جملہ بھی بیان کیا ہے: ((وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ)) ”نہ بچاؤ ہے، نہ طاقت مگر اللہ کی مدد سے۔“ (متفق علیہ)","متفق علیہ",{"k":"بخاری (۶۳۱۷)، مسلم (۷۶۹)، احمد (۲۷۴۸)۔","e":"اس میں اللہ تعالیٰ کی طرف کامل طور پر رجوع کرنے کا بیان ہے کہ ہر حال میں اس کی طرف رجوع کیا جائے اور اس کی مضبوط رسی پکڑنے کا حکم ہے اور صرف اسی کی طرف توجہ کرنے کا درس ہے۔ اور اللہ کے لیے ہی دوستی اور دشمنی رکھنے کا حکم ہے۔ یعنی اس دعاء میں تسلیم و رضا ہر ہر لفظ سے جھلک رہی ہے۔ انتباہ: اس میں جو امام نووی رحمہ اللہ نے کہا ہے کہ بعض راویوں نے اضافہ کیا ہے۔ وہ راوی عبد الکریم بن ابی مخارق ہے ابو امیہ اس کی کنیت تھی بصری معلم ہے۔ مکہ میں رہائش کی تھی۔ اس کے باپ کا نام ایک قول کے مطابق قیس ہے۔ دوسرے قول کے مطابق طارق ہے۔ یہ عبدالکریم ضعیف راوی ہے۔ اس کا بخاری میں ”قیام اللیل“ میں اضافہ ہے جو سفیان، عن، سلیمان الاحول، عن طاووس، عن ابن عباس ہے۔ سفیان کہتے ہیں۔ عبدالکریم نے اضافہ کیا ہے یہ اضافہ متصل سند سے ہے۔ علامہ مزکی رحمہ اللہ نے اس پر تعلیق (روایت کے معلق ہونے) کی علامت لگائی ہے۔ معلق وہ ہے جس کی ساری سند یا بعض حصہ حذف کر دیا جاتا ہے۔ حالانکہ یہ روایت معلق نہیں۔ عبدالکریم کا ذکر مقدمہ مسلم میں بھی گزرا ہے۔ امام نسائی رحمہ اللہ نے بھی اس سے روایات لی ہیں لیکن کم لی ہیں۔ یہ ۱۲۶ھ میں فوت ہوا رحمہ اللہ۔ یہ بعض مشائخ میں جزری کے ساتھ شریک ہوتا ہے یعنی جزری کے اور اس کے بعض استاد ایک ہیں اس وجہ سے جزری کے ساتھ عبدالکریم کا اسے شبہ پڑ جاتا ہے جس کے علم میں یہ بات نہیں جس کی ہم نے وضاحت کی ہے۔ (تقریب: ۲۱۷) اکثر محدثین نے اسے ضعیف قرار دیا ہے۔ حافظ ابن حجر رحمہ اللہ یوں رقمطراز ہیں۔ بخاری میں عبدالکریم کا ذکر صرف اسی جگہ پر ہے کسی اور جگہ پر نہیں۔ بخاری رحمہ اللہ نے اس کا ذکر مقصد کتاب کے طور پر نہیں کیا۔ یہ صرف بتانے کے لیے کیا ہے کہ عبدالکریم نے لَا حَوْلَ وَلَا قُوَّةَ کا اضافہ بیان کیا ہے۔ اس سے استدلال نہیں کیا۔ استدلال اس اضافہ سے پہلے مذکور حدیث سے ہی کیا ہے یہی وجہ ہے کہ عبدالکریم کو بخاری کے راویوں میں شمار نہیں کرتے۔ منذری نے کہا ہے کہ بخاری نے عبدالکریم کے ساتھ حجت پکڑی ہے۔ اور حوالہ اسی حدیث (۶۳۱۷) کتاب التهجد کا دیا ہے۔ یہ ان کی بات درست نہیں۔ کیونکہ اسے بیان کرنا امام بخاری رحمہ اللہ کے مقصد میں سے نہیں نہ ہی حجت کے لیے اسے بیان کیا ہے حجت تو اس سے پہلے ہے یہ تو صرف سند کے متصل ہونے کی وضاحت کے لیے بیان کیا ہے۔ یہ متصل ہونے کے باوجود ضعیف راوی ہے استدلال کے قابل نہیں۔ ابن طاہر نے بھی کہا ہے کہ بخاری اور مسلم نے کتاب الحج میں حدیث بیان کی ہے۔ جو عبدالکریم سے ہے۔ یہ انہیں غلطی لگی ہے۔ یہ عبد الکریم بن ابی مخارق نہیں وہ تو عبدالکریم جزری ہے وہ ثقہ ہے۔ (فتح الباری: ۱۱/ ص ۵)","m":"اَنَبْتُ (افعال) (اجوف واوی) ماضی واحد متکلم۔ میں نے رجوع کیا۔"}],[1480,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم ان الفاظ کے ساتھ دعا کیا کرتے تھے: ((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ فِتْنَةِ النَّارِ، وَعَذَابِ النَّارِ، وَمِنْ شَرِّ الْغِنَى وَالْفَقْرِ)) ”یا اللہ! میں تیری پناہ چاہتا ہوں جہنم کی آزمائش سے اور جہنم کے عذاب سے اور امیری اور غریبی کے شر سے۔“ (ابو داؤد، ترمذی۔ امام ترمذی نے فرمایا: یہ حدیث حسن صحیح ہے۔ اور یہ الفاظ ابو داؤد کے مطابق ہیں۔)","حسن صحیح",{"k":"ابوداؤد (۱۵۴۳)، ترمذی (۳۴۹۵، ۷۶)، احمد (۲۴۳۰۱)، ابن ماجہ (۳۸۳۸)، نسائی (۸؍۲۶۲)، بخاری (۶۳۶۸)، مسلم (۶۸۷۱)۔","e":"آگ کا فتنہ یہ ہے کہ اس میں ڈال کر آزمایا جائے اور غنا کا فتنہ یہ ہے کہ حلال اور حرام مال میں تمیز کئے بغیر اسے جمع کرنے کا لالچ ہو جائے اور انسان مال میں کنجوسی کرنے لگ جائے، تکبر کا شکار ہو جائے اور عیش پروری شروع کر دے اور فقر کا فتنہ یہ ہے کہ انسان تنگ دل ہو جاتا ہے۔ نا امیدی اسے جکڑ لیتی ہے اور تقدیر پر اعتراض شروع کر دیتا ہے۔ اس میں آگے سے خوفزدہ کیا گیا ہے کہ انسان اس چیز سے دور رہے اور ان نافرمانیوں سے بچے جہنم کی آگ کا باعث ہیں۔ ایسے فتنوں سے دور رہنا چاہیے جو جہنم میں جانے کا باعث ہوں۔ انسان کی آزمائش کبھی امیری سے ہوتی ہے کبھی غریبی سے ہوتی ہے۔ امیری میں ایسے اسباب سے دور رہا جائے جو انسان کے لیے نقصان دہ ہیں جیسے کہ تکبر، فخر، غرور اور مال جمع کرنے کی حرص و آز۔ نیز حرام طریقے سے مال جمع کرنا اور پھر ادائے حق میں بخل سے کام لینا تنگ دستی کے عالم میں بھی ہلاکت کے اسباب سے بچنا چاہیے جیسے تقدیر کا گلہ شکوہ، اللہ تعالیٰ پر اعتراض کرنا، حسد کی آگ میں جلنا یا حرام ذرائع سے مال اکٹھا کرنا۔"}],[1481,"سیدنا زیاد بن علاقہ نے اپنے چچا جان سیدنا قطبہ بن مالک رضی اللہ عنہ سے روایت کرتے ہیں کہ نبی صلی اللہ علیہ وسلم فرمایا کرتے تھے: ((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ مُنْكَرَاتِ الْأَخْلَاقِ، وَالْأَعْمَالِ، وَالْأَهْوَاءِ)) ”یا اللہ! میں تیری پناہ میں آتا ہوں بُری عادتوں سے، بُرے کاموں سے اور بُری خواہشات سے۔“ (اسے ترمذی نے روایت کیا اور فرمایا: یہ حدیث حسن ہے۔)","حسن",{"k":"ترمذی (۳۵۹۱)، ابن حبان (۹۶۰)، حاکم (۱؍۵۳۲)۔","e":"اخلاق و اعمال کی دو قسمیں ہیں۔ (۱) مذمومہ (برے اعمال اور اخلاق) (۲) محمودہ (اچھے اعمال و اخلاق) جو آپ صلی اللہ علیہ وسلم کی سنت کے مطابق اعمال اور اخلاق ہوں گے وہ محمود ہیں اور جو اس کے مخالف ہوں گے وہ مذموم ہیں۔ اس حدیث میں یہی دعاء سکھائی گئی ہے کہ اپنے اعمال، اپنے اخلاق اپنی خواہشات سب کو اللہ تعالیٰ اور رسول اکرم صلی اللہ علیہ وسلم کے احکام کے مطابق کریں۔","r":"زیاد بن علاقہ ثعلبی کوفی ہیں۔ ان کی کنیت ابو مالک ہے۔ تابعی ہیں۔ اپنے چچا قطبہ بن مالک، جریر بجلی اور اسامہ بن شریک سے روایات لیتے ہیں۔ اعمش، مسعر، شعبہ ان کے شاگرد ہیں۔ قطبہ بن مالک کوفہ میں رہے تھے صحابی ہیں۔ دو احادیث بیان کی ہیں۔ ابن معین اور امام نسائی نے انہیں یعنی زیاد کو ثقہ قرار دیا ہے۔ ابن ابی حاتم نے صدوق کہا ہے۔ ۱۳۵ھ میں فوت ہوئے۔"}],[1482,"سیدنا شکل بن حمید رضی اللہ عنہ سے روایت ہے کہ انہوں نے فرمایا: میں نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم! مجھے کوئی دعا سکھا دیجئے۔ آنحضرت صلی اللہ علیہ وسلم نے فرمایا: ”کہو: ((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ سَمْعِي، وَمِنْ شَرِّ بَصَرِي، وَمِنْ شَرِّ لِسَانِي، وَمِنْ شَرِّ قَلْبِي، وَمِنْ شَرِّ مَنِيِّ)) یا اللہ! میں تیری پناہ چاہتا ہوں، میرے کانوں کے شر سے، میری آنکھوں کے شر سے، میری زبان کے شر سے، میرے دل کے شر سے اور میرے مادہ تولید کے شر سے۔“ (ابو داؤد، ترمذی۔ انہوں نے فرمایا: یہ حدیث حسن ہے۔)","حسن",{"k":"ابوداؤد (۱۵۵۱)، ترمذی (۳۴۹۲)، احمد (۱۵۵۴۱)، نسائی (۸؍۲۵۹)۔","e":"اس میں ترغیب ہے کہ کان، آنکھ، زبان، دل اور شرمگاہ کی حفاظت کی جائے۔ اور ان اعضاء کو رضائے الہی میں استعمال کیا جائے۔ کیونکہ ان اعضاء اور حواس کے متعلق سوال کیا جائے۔ ارشاد باری ہے: ﴿إِنَّ السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ كُلُّ أُولَئِكَ كَانَ عَنْهُ مَسْئُولًا﴾ (اسراء: ۳۶) بے شک کان، آنکھ، دل ہر ایک کے متعلق سوال کیا جائے گا۔ یہ اعضاء اللہ کی نعمت ہیں انہیں جس مقصد کے لیے پیدا کیا گیا ہے اسی میں استعمال کریں تو ان کا شکر اداء ہوتا ہے۔ اور انہیں اس لیے بھی نیک کاموں میں استعمال کیا جائے کہ انہوں نے روز قیامت گواہی بھی دینی ہے۔","r":"شکل بن حمید عبسی کوفی ہیں۔ ان کا شمار صحابہ کرام رضی اللہ عنہم میں ہوتا ہے۔ آپ سے صرف یہی ایک حدیث مروی ہے کہ آپ ایک دفعہ نبی اکرم صلی اللہ علیہ وسلم کے پاس گئے اور عرض کی۔ اے اللہ کے رسول صلی اللہ علیہ وسلم! مجھے کوئی دعاء سکھائیں جس کے ذریعے سے میں پناہ مانگا کروں۔ تو انہیں نبی صلی اللہ علیہ وسلم نے یہ دعاء سکھائی۔ رضی اللہ عنہ۔"}],[1483,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم فرمایا کرتے تھے: ((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْبَرَصِ، وَالْجُنُونِ، وَالْجُذَامِ، وَسَيِّئِ الْأَسْقَامِ)) ”یا اللہ! تیری پناہ میں آتا ہوں، برص (سفید دانوں کے مرض سے) اور پاگل پن سے اور کوڑھ سے اور بُری بیماریوں سے۔“ (اسے ابو داؤد نے صحیح سند سے روایت کیا ہے۔)","صحیح",{"k":"ابوداؤد (۱۵۵۴)، نسائی (۵؍۲۷۰)، احمد (۱۳۰۰۴)۔\nابوداؤد (الوتر) باب فى الاستعاذة۔","e":"ان تمام تباہ کن امراض سے اللہ کی پناہ طلب کی گئی ہے۔ وجہ یہ ہے کہ یہ انسان کے صبر کی آزمائش بن جاتی ہیں اور صبر کی وجہ سے جو اجر ملنا ہوتا ہے یہ اس سے محرومی کا باعث بن جاتی ہیں۔ اسی وجہ سے نبی صلی اللہ علیہ وسلم نے تمام بیماریوں سے اللہ کی پناہ نہیں مانگی ایک تو ممکن نہیں کہ بندہ بھی بیمار نہ ہو دوسرا اور اگر بیماری آئے انسان صبر کرے تو اللہ تعالیٰ اسے گناہوں کا کفارہ بنا دیتے ہیں اور اجر بھی دیتے ہیں۔"}],[1484,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے: ((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْجُوعِ، فَإِنَّهُ بِئْسَ الضَّجِيعُ، وَأَعُوذُ بِكَ مِنَ الْخِيَانَةِ، فَإِنَّهَا بِئْسَتِ الْبِطَانَةُ)) ”یا اللہ! میں بھوک سے تیری پناہ مانگتا ہوں، وہ بستر کا بُرا ساتھی ہے، اور میں خیانت سے تیری پناہ مانگتا ہوں، وہ بُرا ہم راز ہے۔“ (اسے ابو داؤد نے صحیح سند سے روایت کیا ہے۔)","صحیح",{"k":"ابوداؤد (۱۵۷۴)، نسائی (۵۴۶۸)، ابن ماجہ (۳۳۵۴)، ابن حبان (۱۰۲۹)۔","e":"اور اس میں ادائے امانت کی ترغیب ہے اور ہر حال میں اچھے اخلاق پر ثابت قدمی اور استقامت کی ترغیب ہے اور اگر کسی شخص میں کوئی بری خصلت ہو تو وہ اس کی فوراً اصلاح کرے۔"}],[1485,"سیدنا علی رضی اللہ عنہ سے روایت ہے کہ ایک مکاتب (1) نے ان کی خدمت میں حاضر ہو کر عرض کی: میں (آزادی کے لیے معاہدے کی رقم ادا کرنے سے عاجز آ گیا ہوں۔ میری مدد کیجئے: سیدنا علی رضی اللہ عنہ نے فرمایا: کیا میں تجھے کچھ الفاظ نہ سکھا دوں، جو مجھے رسول اللہ صلی اللہ علیہ وسلم نے سکھائے تھے؟ اگر تجھ پر پہاڑ جتنا قرض بھی ہوگا تو (اس دعا کی برکت سے اللہ تعالیٰ تیرا قرض ادا کر دے گا۔ تو پڑھا کر: ((اللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ)) ”یا اللہ! اپنے حرام سے بچا کر اپنے حلال کے ساتھ میری کفایت فرما اور اپنے فضل کے ساتھ مجھے تیرے سوا سب سے بے نیاز کر دے۔“ (ترمذی۔ انہوں نے فرمایا: یہ حدیث حسن ہے۔)","حسن",{"k":"ترمذی (۳۵۶۳، ۱۰۰)، احمد (۱؍۱۵۳)، حاکم (۱؍۵۳۸)۔","e":"یہ ایسی دعاء ہے اس کی برکت سے قرض پورا اداء ہو جاتا ہے۔ کیونکہ اس میں لوگوں کی بجائے اللہ کے ساتھ رابطہ کیا گیا ہے۔ ایک روایت میں اس پہاڑ کا نام بھی آیا ہے کہ شبیر پہاڑ جتنا قرض تھا تو اداء ہو جائے گا۔ اس میں مکاتب کی مدد کی ترغیب ہے مکاتب وہ غلام ہے جو اپنے مالک سے معاہدہ کر لیتا ہے اگر میں اتنی رقم ادا کر دوں تو میں آزاد ہوں۔ اور یہ بھی ثابت ہوا کہ مقروض اپنے قرض کی ادائیگی کے مطابق کسی سے مانگ سکتا ہے۔ بلاضرورت سوال کی ممانعت ہے اور رزق حلال تھوڑا بھی ہو تو وہ اس رزق سے بہتر ہے جو حرام ہو اور زیادہ ہو۔ ہر قسم کا فضل صرف اللہ کے ہاتھ میں ہے اور ہر طرح کی خیر و بھلائی کا منبع اللہ کی ذات گرامی ہے۔ اس لیے بندہ صرف اسی سے مدد مانگے تو قرض کی ادائیگی کے لیے یہ بہترین دعاء ہے۔","m":"مُكَاتَبًا وہ غلام جو قسطوں پر آزاد ہو۔ اَعِنِّي (افعال) (اجوف واوی) امر واحد مذکر حاضر نون وقایہ یاء مفعول بہ۔ میری مدد کیجیے۔ أَدَّاهُ (تفعیل) (مہموز الفاء اور مضاعف) ماضی واحد مذکر غائب ضمیر مفعول بہ۔ اسے اداء کر دے گا۔ اِكْفِنِي (ض) (ناقص یائی) امر واحد مذکر حاضر نون وقایہ یاء مفعول بہ۔ مجھے کفایت کرو۔ وَأَغْنِنِي (افعال) (ناقص یائی) نون وقایہ یاء مفعول بہ۔ مجھے غنی کردے۔","fn":"(1) جب کوئی غلام اپنے مالک سے یہ معاہدہ کر لے کہ وہ اتنی رقم ادا کر دے گا، اور اس کے عوض اسے آزادی مل جائے گی۔ تو اسے مکاتب اور اس معاہدے کو کِتَابَة يَا مُكَاتَبَة کہتے ہیں۔ (مترجم)"}],[1486,"سیدنا عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ان کے والد حصین (بن عبید خزاعی رضی اللہ عنہ) کو جملے سکھائے کہ ان کے ساتھ دعا کیا کریں: ((اللَّهُمَّ أَلْهِمْنِي رُشْدِي، وَأَعِذْنِي مِنْ شَرِّ نَفْسِي)) ”یا اللہ! میرے دل میں میری ہدایت ڈال دے اور مجھے میرے نفس کے شر سے پناہ میں رکھ۔“ (ترمذی۔ انہوں نے فرمایا: یہ حدیث حسن ہے۔)","حسن",{"k":"ترمذی (۳۴۸۳، ۷۰)، تاریخ کبیر بخاری (۳؍۱)، احمد (۱۹۹۹۲)۔\nبیہقی فی الاسماء والصفات: ۵۳۴۔\nدارمی فی الرد علی المریسی: ۲۴۔","e":"اس میں تمام امور کے بارے میں استقامت اور سیدھے پن اور طلب ہدایت کی دعاء ہے اور نفسانی شرارتوں سے بچاؤ کی دعاء ہے کیونکہ جو شخص اپنے نفس کے سپرد ہوتا ہے وہ ہلاک ہو جاتا ہے اس لیے دعاء کرنی چاہیے کہ ایک لمحہ بھر کے لیے ہمیں ہمارے نفسوں کے سپرد نہ کرے اور ایمانداروں سے مطلوب بھی رشد و ہدایت ہے۔ ارشاد باری ہے: ﴿وَلَكِنَّ اللَّهَ حَبَّبَ إِلَيْكُمُ الْإِيمَانَ وَزَيَّنَهُ فِي قُلُوبِكُمْ وَكَرَّهَ إِلَيْكُمُ الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ أُولَئِكَ هُمُ الرَّاشِدُونَ﴾ (الحجرات: ۷) لیکن اللہ نے تمہاری طرف ایمان کو پسندیدہ کر دیا ہے اور اسے تمہارے دلوں میں مزین کیا ہے اور کفر، فسق اور نافرمانی کو مکروہ کر دیا ہے یہی لوگ رشد و ہدایت والے ہیں۔ انتباہ: علامہ ہلالی نے اسے ضعیف کہا ہے۔ اس کی سند میں شعیب ہے۔ یہ صدوق ہے مگر اسے وہم ہوتا ہے۔ اور حسن راوی مدلس ہے وہ یہاں عن سے بیان کر رہا ہے۔ (بہجة الناظرين: ۲/ ص ۳۶۳) مگر علامہ ارناءوط رحمہ اللہ نے حسن قرار دیا ہے۔ اور علامہ عثیمین رحمہ اللہ نے اس کی سند کو صحیح کہا ہے۔ (ص ۱۲۶۵)","m":"أَلْهِمْنِي (افعال) (صحیح) امر واحد مذکر حاضر نون وقایہ یاء مفعول بہ۔ مجھے الہام کر دے۔ أَعِذْنِي (افعال) (اجوف واوی) نون وقایہ یاء مفعول بہ امر حاضر۔ تو مجھے پناہ دے۔"}],[1487,"سیدنا ابو الفضل عباس بن عبدالمطلب رضی اللہ عنہ سے روایت ہے کہ انہوں نے فرمایا: میں نے عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم! مجھے کوئی چیز سکھائیں جو میں اللہ تعالیٰ سے مانگ لوں۔ آنحضرت صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالیٰ سے عافیت مانگو، چند دن ٹھہر کر میں پھر حاضر خدمت ہوا اور عرض کی: اللہ کے رسول صلی اللہ علیہ وسلم! مجھے کوئی چیز سکھائیں جو میں اللہ تعالیٰ سے مانگوں۔ آپ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: اے عباس! اے رسول اللہ صلی اللہ علیہ وسلم کے چچا! تم لوگ اللہ تعالیٰ سے دنیا اور آخرت میں عافیت مانگا کرو۔“ (ترمذی۔ انہوں نے فرمایا: یہ حدیث حسن صحیح ہے۔)","حسن صحیح",{"k":"ترمذی (۳۵۱۴)، احمد (۱۷۸۳)، الادب المفرد بخاری (۷۲۶)، ابن ماجہ (۳۸۴۸)۔","e":"عافیت کا مطلب ہے ہر اذیت ناک چیز سے اللہ دور رکھے۔ اس میں بیماریوں اور گناہوں سے بچاؤ بھی شامل ہے لہذا دنیا و آخرت کی عافیت طلب کی جائے۔ اللہ تعالیٰ خود سلامتی والے ہیں اس لیے ان سے دنیا و آخرت کی عافیت اور سلامتی طلب کی جائے۔ جیسے یہ عافیت مل گئی اسے دنیا و آخرت کی ہر خیر مل گئی۔ دنیا میں عافیت یہ ہے کہ بیماریوں اور آلام و مصائب اور فتنوں سے سلامتی رہے۔ اور آخرت کی عافیت یہ ہے کہ گناہوں کی معافی اور اللہ تعالیٰ کا قرب ہو۔ یہ بھی ثابت ہوا کہ صحابہ کرام رضی اللہ عنہم رشد و ہدایت اور خیر کے حصول کے لیے بہت زیادہ جستجو کرتے رہتے تھے۔ اس کی سند میں ضعف ہے لیکن اس کا شاہد (تائید والا متن) موجود ہے۔ اس لیے یہ حسن ہے۔"}],[1488,"سیدنا شہر بن حوشب رضی اللہ عنہ سے روایت ہے کہ انہوں نے فرمایا: میں نے ام سلمہ رضی اللہ عنہا سے عرض کی: ام المومنین! جب رسول اللہ صلی اللہ علیہ وسلم آپ کے پاس (آپ کے گھر میں) ہوتے تھے، تو آپ صلی اللہ علیہ وسلم سب سے زیادہ کون سی دعاء کرتے تھے؟ انہوں نے فرمایا: آپ صلی اللہ علیہ وسلم کی دعاء سب سے زیادہ یہ ہوتی تھی: ((يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى دِينِكَ)) ”اے دلوں کو پھیرنے والے! میرا دل اپنے دین پر پختگی سے قائم رکھنا۔“ (اسے ترمذی نے روایت کیا۔ انہوں نے فرمایا: یہ حدیث حسن ہے۔)","حسن",{"k":"ترمذی (۳۵۲۲)، احمد (۲۶۶۷۹)، الشریعه آجری (۳۱۶)، تفسیر ابن کثیر (۲؍۲۹۸)۔\nالسنہ ابن ابی عاصم (۲۲۳)۔\nصحیح بشواہدہ۔","e":"اس میں نبی صلی اللہ علیہ وسلم جو اپنے رب کے سامنے خشوع و خضوع کرتے تھے اس کا بیان ہے اور آپ کی تواضع کا تذکرہ ہے۔ اس میں آپ صلی اللہ علیہ وسلم نے اپنی امت کو تعلیم دی ہے کہ یہ دعاء کرے۔ اس میں استقامت اور دین پر ثابت قدمی کا بھی اشارہ ہے کہ یہ بہت ہی اہم بات ہے اور یہ بھی اشارہ ہے کہ اعتبار خاتمہ کے مطابق ہوگا۔ بندوں کا دل اللہ کے ہاتھ میں ہے وہ جدھر چاہتا ہے پلٹ دیتا ہے اس لیے اس سے دعاء کی گئی ہے۔ دین پر اسے ثابت رکھنا۔ اس سے یہ بھی ثابت ہوا کہ اسلام پر ثابت قدمی بہت بڑی نعمت ہے بندے کو اس کی کوشش کرتے رہنا چاہیے۔ کیونکہ بندہ اللہ کی توفیق کے بغیر ایک لمحہ بھی اسلام پر ثابت قدم نہیں رہ سکتا۔ اور اگر اللہ تعالیٰ ثابت قدمی سے نہ نوازیں تو ایمان کی ساری عمارت ہی زمین بوس ہو جائے۔ اسی لیے میت کو دفن کرنے کے بعد اس کے لیے ثابت قدمی کی دعاء کی جاتی ہے۔ ثابت قدمی کے اللہ تعالیٰ نے اسباب بیان کئے ہیں: (۱) اللہ تعالیٰ کے ذکر سے بھی ثابت قدمی ہوتی ہے۔ (الرعد: ۲۸) (۲) تربیت ایمان کے مطابق ہو تو یہ بھی ثابت قدمی کا باعث ہے۔ (۳) اس بات کا یقین ہو کہ مستقبل میں اسلام غالب ہوگا یہ جذبہ بھی ثابت قدمی کا باعث ہے۔","r":"سیدنا شہر بن حوشب رضی اللہ عنہ حضرت اسماء بنت یزید بن سکن کے آزاد کردہ غلام تھے۔ ان کی کنیت ابوسعید شامی ہے۔ تابعی ہیں۔ ثقہ ہیں۔ ان کے متعلق تمام لوگوں کے خیالات اچھے ہیں۔ ۱۰۰ھ میں فوت ہوئے۔"}],[1489,"سیدنا ابو درداء رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”حضرت داؤد علیہ السلام کی ایک دعاء یہ بھی ہوتی تھی: ((اللَّهُمَّ إِنِّي أَسْأَلُكَ حُبَّكَ، وَحُبَّ مَنْ يُحِبُّكَ، وَالْعَمَلَ الَّذِي يُبَلِّغُنِي حُبَّكَ، اللَّهُمَّ اجْعَلْ حُبَّكَ أَحَبَّ إِلَيَّ مِنْ نَفْسِي، وَأَهْلِي، وَمِنَ الْمَاءِ الْبَارِدِ)) یا اللہ! میں تجھ سے تیری محبت مانگتا ہوں، اور تجھ سے محبت رکھنے والوں کی محبت اور وہ عمل جو مجھے تیری محبت تک پہنچا دے۔ یا اللہ! تو اپنی محبت کو، مجھے میری جان سے، میرے اہل وعیال سے اور ٹھنڈے پانی سے بھی زیادہ محبوب کر دے۔“ (اسے ترمذی نے روایت کر کے فرمایا: یہ حدیث حسن ہے۔)","حسن",{"k":"ترمذی (۳۴۹۰)، حاکم (۲؍۴۳۳)، ابن عساکر (۵؍۳۵۲)۔","e":"اس میں ترغیب ہے کہ اللہ تعالیٰ کی محبت طلب کی جائے اور یہ حاصل ہوتی ہے عمل صالح سے اور رسول اکرم صلی اللہ علیہ وسلم کی اتباع سے۔ ارشاد باری ہے: ﴿قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ﴾ (آل عمران: ۳۱) فرمادیجیے اگر تم اللہ سے محبت چاہتے ہو تو میری اتباع کرو اللہ تعالیٰ تم سے محبت کریں گے۔ اس میں یہ بھی بتایا گیا ہے اللہ تعالیٰ اور رسول اکرم صلی اللہ علیہ وسلم کی اطاعت اپنی جان اور اپنے اہل و عیال اور اپنی خواہشات پر مقدم رکھی جائے۔ جب اللہ تعالیٰ سے محبت ہو اور جس سے اللہ محبت رکھتے ہیں ان سے محبت ہو جائے تو یہ چیز بھی اللہ کا دوست بنا دیتی ہے۔ اس میں اللہ تعالیٰ سے محبت رکھنے کی ترغیب ہے اور اس کی تگ و دو کی ترغیب ہے۔ اس میں یہ بھی بتایا گیا ہے کہ نیک لوگوں کی محبت طلب کی جائے اور اس میں بتایا گیا ہے کہ ایسے کام کرنے کی دعاء کی جائے جو اللہ کی محبت کے قریب کر دیں۔ انتباہ: اس حدیث میں ایک راوی عبداللہ بن ربیعہ بن یزید مشتقی مجہول ہے جس کی وجہ سے ترمذی کی اس حدیث کو ضعیف قرار دیا گیا ہے۔ (البانی، ہلالی، ارناءوط رحمہ اللہ) لیکن علامہ عبداللہ رحمانی رحمہ اللہ فرماتے ہیں: التاریخ الکبیر: اس میں بخاری رحمہ اللہ نے اس عبداللہ بن یزید بن ربیعہ مشتقی کا تذکرہ کیا ہے مگر اس پر نہ تو جرح کی ہے نہ عدل والا کہا ہے اور ابن حبان نے اسے ثقات راویوں میں ذکر کیا ہے۔ (التہذیب: ۵/ ص ۲۰۸) ہر صورت امام ترمذی کا اسے حسن قرار دینا درست ہے۔ (مرعاة المفاتیح: ۶/ ص ۱۶۶)","m":"يُحِبُّكَ (افعال) (مضاعف) مضارع معلوم واحد مذکر غائب ضمیر حاضر مفعول بہ۔ وہ تجھ سے محبت کرتا ہے۔"}],[1490,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ((أَلِظُّوا بِيَا ذَا الْجَلَالِ وَالْإِكْرَامِ)) ”اے جلال اور عزت والے! کا التزام کرو۔“ (اسے ترمذی نے روایت کیا ہے۔ نسائی نے اسے سیدہ ربیعہ بن عامر رضی اللہ عنہ سے روایت کیا ہے اور وہ صحابی ہیں۔ حاکم نے فرمایا: اس حدیث کی سند صحیح ہے۔)","صحیح الاسناد",{"k":"ترمذی (۳۵۲۵)، سنن کبریٰ نسائی (۶؍۴۷۹)، احمد (۴؍۱۷۷)، مستدرک (۱؍۴۹۸)۔","e":"جلال و اکرام دو صفات ہیں یہ اللہ کی الوہیت میں بہت اہم ہیں۔ ایک قول ہے کہ ذوالجلال والاکرام اللہ کا اسم اعظم ہے۔ اس میں ترغیب ہے کہ اللہ تعالیٰ سے کثرت سے دعاء کی جائے اور دعاء کا آغاز ان دو صفات کے ساتھ کیا جائے۔","m":"☆ اَلِظُّوا: لام کے کسرہ اور نقطے والی ظاء کی تشدید سے ہے۔ یعنی اس دعا کو ہمیشہ پڑھو۔ اور کثرت سے پڑھو۔"}],[1491,"سیدنا ابو امامہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے (ایک بار) بہت سی دعائیں مانگیں، ہمیں ان میں سے کوئی بھی یاد نہ ہوئی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: کیا میں تمہیں وہ چیز نہ بتاؤں جو ان سب دعاؤں کی جامع ہو؟ تم کہو: ((اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ مِنْهُ نَبِيُّكَ مُحَمَّدٌ صلى الله عليه وسلم وَأَعُوذُ بِكَ مِنْ شَرِّ مَا اسْتَعَاذَ مِنْهُ نَبِيُّكَ مُحَمَّدٌ صلى الله عليه وسلم، وَأَنْتَ الْمُسْتَعَانُ، وَعَلَيْكَ الْبَلَاغُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ)) ”یا اللہ! میں تجھ سے ہر اس خیر کا سوال کرتا ہوں، جو تجھ سے تیرے نبی محمد صلی اللہ علیہ وسلم نے مانگی ہے، اور میں ہر اس شر سے تیری پناہ میں آتا ہوں، جس سے تیرے نبی محمد صلی اللہ علیہ وسلم نے تیری پناہ مانگی ہے، یہی ہے مدد طلب کی جاتی ہے اور (خیر اور بھلائی) پہنچانا تیرا ہی کام ہے۔ اور اللہ کی توفیق کے بغیر نہ (گناہ اور مصیبت سے) بچاؤ ہو سکتا ہے نہ (نیکی اور نعمت کے حصول کی) طاقت مل سکتی ہے۔“ (اسے ترمذی نے روایت کر کے فرمایا: یہ حدیث حسن ہے۔)","حسن",{"k":"ترمذی (۳۵۲۱)۔","e":"اس دعاء کو ہمیشہ کرنے کی ترغیب ہے۔ یہ نبی صلی اللہ علیہ وسلم کی تمام دعاؤں کی جامع دعاء ہے اور اس دعاء کا اسے خاص فائدہ ہوگا جسے نبی صلی اللہ علیہ وسلم کی دعائیں یاد نہیں۔ اس سے اسلام کی آسانی اور بندوں پر جو اللہ تعالیٰ کی رحمت کی ارزانی ہے وہ معلوم ہوتی ہے کہ جامع کلمات سے اسلام نے آگاہ کیا ہے۔ انتباہ: بعض محقق اسے لیث بن ابی سلیم کی وجہ سے وہ کمزور حافظہ والا ہے اس حدیث کو ضعیف قرار دیتے ہیں۔ لیکن علامہ ارناءوط رحمہ اللہ کی تحقیق یہ ہے کہ احمد: ۶/ ص ۱۳۴۔ عن عائشہ۔ ابن ماجہ: ۳۸۴۶ میں شاہد (تائید والی حدیث) موجود ہے۔ اسے ابن حبان نے صحیح قرار دیا ہے۔ (۳۴۱۳) ابن حبان۔ اور لیث بن ابی سلیم کے باوجود یہ حسن درجہ سے کم نہیں۔ البانی نے صحیح کہا ہے۔ (تفہیم الاسلام: ۲/ ص ۹۹۷)","m":"اِسْتَعَاذَ (استفعال) (اجوف واوی) ماضی واحد مذکر غائب۔ اس نے پناہ طلب کی۔ الْمُسْتَعَانُ (استفعال) (اجوف واوی) اسم مفعول واحد مذکر جس سے مدد طلب کی جاتی ہے۔"}],[1492,"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کی ایک دعاء یہ بھی ہوتی تھی: ((اللَّهُمَّ إِنِّي أَسْأَلُكَ مُوجِبَاتِ رَحْمَتِكَ، وَعَزَائِمَ مَغْفِرَتِكَ، وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ، وَالْغَنِيمَةَ مِنْ كُلِّ بِرٍّ، وَالْفَوْزَ بِالْجَنَّةِ، وَالنَّجَاةَ مِنَ النَّارِ)) ”یا اللہ! میں تجھ سے تیری رحمت کو واجب کرنے والی چیزوں کا، تیری مغفرت کے اسباب کا، ہر گناہ سے بچاؤ کا، ہر نیکی کی غنیمت حاصل ہونے کا، جنت کے حصول میں کامیابی کا، اور جہنم سے نجات پانے کا سوال کرتا ہوں۔“ (اسے امام ابو عبداللہ حاکم نے روایت کر کے فرمایا: یہ حدیث امام مسلم کے معیار کی صحیح ہے۔)","صحیح علی شرط مسلم",{"k":"مستدرک حاکم (۱؍۵۲۵)۔","e":"اس میں نیکی میں اطاعت اور کاموں کی جدوجہد کی ترغیب ہے اور نافرمانیوں اور بُرے کاموں سے دوری کی رغبت کی۔ امام نووی رحمہ اللہ نے دعا کے باب کو اس حدیث پر ختم کیا ہے۔ اس میں اہم نکتہ ہے کہ دعاء وہ بھی حقوق اللہ میں سے اور یہ اعمال میں شمار ہوتی ہے۔ اس میں دوزخ سے نجات کا سوال ہے اور جنت میں سلامتی سے داخلہ کی عرض ہے۔ ارشاد باری بھی ہے: ﴿فَمَنْ زُحْزِحَ عَنِ النَّارِ وَأُدْخِلَ الْجَنَّةَ فَقَدْ فَازَ﴾ (آل عمران: ۱۸۵) جو دوزخ سے ہٹا دیا گیا اور جنت میں داخل کیا گیا وہ کامیاب ہوا مقصود دعاء یہ ہے کہ اللہ تعالیٰ سے ان اعمال کی توفیق طلب کرتا ہے جن سے اس کی رحمت و مغفرت حاصل ہو۔ اور گناہوں سے تحفظ ملے اور اعمال خیر کی رغبت پیدا ہو اور بالآخر جہنم سے نجات ملے اور جنت کی سرفرازی حاصل ہو جائے۔ انتباہ: اس کی سند میں حمید اعرج ہے ذہبی نے متروک، احمد نے ضعیف اور ابو زرعہ نے واہ (بہت ہی کمزور) کہا ہے دارقطنی نے بھی متروک کہا ہے۔ جو ماخذ ہمیں میسر آئے ہیں ان کے محققین نے اسے ضعیف قرار دیا ہے۔ تنہا امام نووی رحمہ اللہ کی تحقیق اسے شرط مسلم کے مطابق تسلیم کرتی ہے۔ دوسرے اسے ضعیف کہتے ہیں۔"}],[1493,"سیدنا ابو درداء رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے یہ فرمان سنا: ”جو مسلمان بندہ اپنے مسلمان بھائی کے لیے اس کی غیر موجودگی میں دعاء کرتا ہے، فرشتہ (اس کے حق میں دعاء کرتے ہوئے) کہتا ہے۔ تجھے بھی ویسی ہی چیز ملے۔“ (مسلم)","",{"k":"مسلم (۲۷۳۲)، احمد (۲۷۵۰۸)۔","e":"اس میں مسلمان بھائی لیے غائبانہ دعاء کی فضیلت ہے کہ جب آدمی غائبانہ دعاء کرتا ہے جو دعاء یہ اپنے بھائی کے لیے کرتا ہے فرشتے یہ دعاء کرتے ہیں کہ اللہ کریم اس دعاء کرنے والے نے جو اپنے بھائی کے لیے دعاء کی ہے وہی کچھ اسے بھی عطاء کر دے اور فرشتے معصوم ہوتے ہیں لہذا دوسروں کو دعاؤں میں شریک کر کے ان کی دعاؤں کو حاصل کریں۔ اس لیے ہر مسلمان کو چاہیے کہ اپنے حق میں دعاء کے ساتھ اپنے دیگر اعزہ و اقارب کے حق میں اور اپنے والدین کے حق میں دعاء کریں۔","i":"اللہ تعالیٰ نے فرمایا: ﴿وَالَّذِينَ جَاءُوا مِنْ بَعْدِهِمْ يَقُولُونَ رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ﴾ (الحشر: ۱۰) ”اور جو ان کے بعد آئے وہ کہتے ہیں: ہمارے رب ہمیں بھی بخش دے اور ہمارے ان بھائیوں کو بھی جو ہم سے پہلے ایمان لائے۔“ اور فرمایا: ﴿وَاسْتَغْفِرْ لِذَنْبِكَ وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ﴾ (محمد: ۱۹) ”اپنی لغزش کی معافی بھی مانگتے اور مومن مردوں اور مومن عورتوں کے لیے بھی مغفرت کی دعا کیجئے۔“ اور اللہ تعالیٰ نے حضرت ابراہیم علیہ السلام کے بارے میں فرمایا کہ انہوں نے فرمایا: ﴿رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ﴾ (ابراہیم: ۴۱) ”ہمارے رب! مجھے بھی بخش دے اور میرے ماں باپ کو بھی اور مومنوں کو بھی جس دن حساب قائم ہوگا۔“ آیات کی تشریح: (۱) سورت الحشر آیت (۱۰) کی تشریح: ارشاد باری ہے: ﴿لِلْفُقَرَاءِ الْمُهَاجِرِينَ الَّذِينَ أُخْرِجُوا مِنْ دِيَارِهِمْ وَأَمْوَالِهِمْ يَبْتَغُونَ فَضْلًا مِنَ اللَّهِ وَرِضْوَانًا وَيَنْصُرُونَ اللَّهَ وَرَسُولَهُ أُولَئِكَ هُمُ الصَّادِقُونَ﴾ (الحشر: ۸) ان مہاجر فقراء کے لیے جنہیں ان کے گھروں اور اولاد سے نکال دیا گیا یہ اللہ کا فضل اور رضا مندی طلب کرتے ہیں۔ اور اللہ تعالیٰ (کے دین) کی اور اس کے رسول صلی اللہ علیہ وسلم کی مدد کرتے ہیں اور یہ لوگ سچے ہیں۔ یہاں اللہ تعالیٰ نے ہجرت اور دین کی نصرت کرنے والوں کی تعریف کی ہے۔ ان کی تعریف کی ہے۔ ارشاد باری ہے: ﴿وَالَّذِينَ تَبَوَّءُوا الدَّارَ وَالْإِيمَانَ مِنْ قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِي صُدُورِهِمْ حَاجَةً مِمَّا أُوتُوا وَيُؤْثِرُونَ عَلَى أَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ وَمَنْ يُوقَ شُحَّ نَفْسِهِ فَأُولَئِكَ هُمُ الْمُفْلِحُونَ﴾ (الحشر: ۹) ”اور وہ لوگ جنہوں نے گھر میں پناہ دی اور ایمان کو جگہ دی ان سے پہلے یہ ان سے محبت رکھتے ہیں جو ان کی طرف ہجرت کرتا ہے اور یہ اپنے سینوں میں تنگی نہیں پاتے جو یہ دیئے گئے ہیں اور یہ دوسروں کو اپنی جانوں پر ترجیح دیتے ہیں اگرچہ انہیں ضرورت ہو۔ اور جو نفس کے بخل سے بچا لیا گیا وہی کامیاب ہے۔“ انصار مدینہ نے مکہ کے مہاجروں کو جگہ دی اور ان سے ہر قسم کا تعاون کیا۔ تو اللہ تعالیٰ انصار کے اس مخلصانہ کارنامے کی تعریف کرتے ہیں۔ غیب میں دعاء کرنا یہ ایمان کی صداقت کی علامت ہے اور بھائی کے لیے محبت کی دلیل ہے اور اس حدیث پر عمل ہے جس میں آیا ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا تم میں سے کوئی ایک وقت تک مومن نہیں ہو سکتا جب تک وہ اپنے بھائی کے لیے وہ کچھ پسند نہ کرے جو وہ اپنے لیے پسند کرتا ہے۔ (بخاری: ۱۳۔ مسلم: ۱۷۰۔ احمد: ۱۲۸۰۱) ظاہر ہے ہر آدمی اپنے لیے دعاء پسند کرتا ہے تو غیب میں بھائی کے لیے دعاء کر کے وہ اس حدیث پر عمل کر کے خود کو ثواب کا مستحق بناتا ہے۔ (۲) سورت محمد آیت (۱۹) کی تشریح: بہت سی احادیث میں آتا ہے کہ نبی اکرم صلی اللہ علیہ وسلم اپنے گناہوں کے لیے استغفار کیا کرتے تھے اور یہ بھی سب جانتے ہیں کہ نبی صلی اللہ علیہ وسلم مومن مردوں اور مومن عورتوں کے لیے بھی استغفار کرتے تھے۔ مغفرت کا معنی ہے گناہ سے تجاوز کرنا۔ مَغْفِرَ سے نکالا گیا ہے۔ مِغْفَر اس لوہے کی ٹوپی کو کہتے ہیں جو سر پر پہنی جاتی ہے اس سے تیر اور تلوار سے حفاظت رہتی ہے۔ (۳) سورت ابراہیم آیت (۴۱) کی تشریح: اس آیت مبارکہ میں سیدنا ابراہیم علیہ السلام مومنوں کے لیے غائبانہ دعاء کر رہے ہیں اور یہ بڑی عظیم سعادت ہے کہ مومنوں کے لیے انبیاء کرام علیہم السلام کے ذریعہ غائبانہ دعاء کرائی جا رہی ہے اور پھر ہر مسلمان مرد اور عورت کے لیے نماز میں غائبانہ دعاء کرتا ہے۔ ہم سب کہتے ہیں۔ اَلسَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ۔ سلامتی ہو ہم پر اور اللہ کے نیک بندوں پر۔ تو یہ اپنے غائب بھائیوں کے لیے دعاء ہے۔ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا۔ جب تم نماز میں یہ کہتے ہو تو آسمان اور زمین کے ہر نیک بندے تک تمہاری یہ سلامتی کی دعاء پہنچتی ہے۔ (بخاری: ۸۳۱۔ مسلم: ۸۹۷۔ احمد: ۳۶۲۲)"}],[1494,"انہی سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مسلمان انسان کی دعاء جو وہ اپنے بھائی کے لیے اس کی غیر موجودگی میں کرتا ہے، قبول ہوتی ہے، اس کے سر کے پاس ایک فرشتہ مقرر ہوتا ہے، جب بھی وہ اپنے بھائی کے لیے کسی (دینیوی یا اخروی) بھلائی کی دعاء کرتا ہے، اس پر مقرر فرشتہ کہتا ہے: آمین! اور تجھے بھی ویسی کچھ ملے۔“ (مسلم)","",{"k":"مسلم (۲۷۳۳)، احمد (۲۱۷۰۷)۔","e":"اس حدیث سے ایک بہت بڑا فائدہ یہ ہوا کہ جب تم اپنے مسلمان بھائی کے لیے پیچھے پیچھے دعاء کرتے ہو تو وہ قبول ہوتی ہے۔ اس لیے کہ وہ آپ کے پاس موجود نہیں اور ہمیں امید ہے کہ تمہارے بارے میں فرشتے کی دعاء بھی قبول ہوگی (الدعاء الماثور و آدابہ ۷۰ ابوبکر طرطوشی) اسلام تمام حالات میں اور اوقات میں مسلمانوں کے درمیان رابطے اور رشتے اخوت کو مضبوط دیکھنا چاہتا ہے۔ غائبانہ دعاء قبولیت کے زیادہ قریب ہے اس لیے کہ اس میں اخلاص اور حضور قلب زیادہ ہوتا ہے یہ کوئی رسمی یا رواجی دعاء نہیں ہوتی۔ اس لیے یہ رد نہیں ہوتی یہ بھی ثابت ہوا کہ غائبانہ دعاء پر آمین کہنے کے لیے باقاعدہ فرشتہ مقرر ہے۔ اس لیے ہمیں چاہیے کہ ہم اپنے لیے اور مسلمان بھائیوں کے لیے اور والدین اور دیگر رشتہ داروں کے لیے غائبانہ دعائیں جاری رکھیں اور دنیا و آخرت کی خیر طلب کرتے رہیں۔ اس میں یہ بھی سبق ہے کہ انسان کا کردار اور عمل ایسا ہونا چاہیے کہ لوگ اس کے لیے غائبانہ دعائیں کریں۔","m":"مُوَكَّلٌ (تفعیل) (مثال واوی) اسم مفعول۔ مقرر کیا گیا ہے۔"}],[1495,"سیدنا اسامہ بن زید رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس کے ساتھ کوئی بھلائی کی گئی، تو اس نے بھلائی کرنے والے کو کہہ دیا: ((جَزَاكَ اللَّهُ خَيْرًا)) ”اللہ تجھے اس کا بہتر بدلہ عطاء فرمائے۔“ اس نے اس کی انتہائی تعریف کر دی۔“ (ترمذی۔ انہوں نے فرمایا: یہ حدیث حسن صحیح ہے۔)","حسن صحیح",{"k":"ترمذی (۲۰۳۵)، ابن حبان (۳۴۱۳)، ابن السنی (۲۷۵)، طبرانی صغیر (۲؍۱۴۸)۔\nنسائی فی عمل الیوم واللیلہ: ۱۸۰۔","e":"اس سے یہ ثابت ہوا کہ مومن کی دعاء قبول ہوتی ہے اور احسان کر کے اسے جتایا نہ جائے اور جو حسن سیرت اور اچھائی کا مظاہرہ کرتا ہے اس کے اس اچھے کردار کا اعتراف کیا جائے۔ اور جزاک اللہ خیر کہا جائے اس کا مطلب یہ ہوتا ہے کہ نیکی کرنے والے! میں تو تیری اس نیکی کا صلہ نہیں دے سکتا۔ اس کی جزا تجھے اللہ ہی دے گا۔ اور یہ ظاہر ہے اللہ کی طرف سے عطاء کردہ جزاء دنیا کے ہر صلہ سے بہتر ہوگی اس لیے رسول اکرم صلی اللہ علیہ وسلم نے فرمایا کہ حسن کے لیے یہ جملہ کہنے میں کمال درجہ کی تعریف ہے۔ اس حدیث میں مسلمانوں کے ساتھ حسن سلوک کرنے کی ترغیب ہے اور یہ بھی تلقین ہے کہ نیکی کرنے والے کو نیک بدلہ دینا چاہیے۔ اور اگر احسان کرنے والے کے احسان کرنے کا بدلہ دینے کی استطاعت نہ ہو تو پھر احسان کرنے والے کے حق میں دعائے خیر کر دی جائے۔ اس میں یہ بھی بتایا گیا ہے کہ اہل فضل کی فضیلت کا اعتراف اور اس کے لیے اچھے جذبات رکھنا مومنوں کا شیوہ ہے۔ اللہ تعالیٰ بندوں کی نسبت پوری پوری اور بہتر جزا دیتا ہے۔ کچھ لوگ جزاک اللہ خیر کے ساتھ یہ اضافہ بھی کرتے ہیں۔ اَطْعَمَكَ اللَّهُ طَيْرًا وَزَوَّجَكَ اللَّهُ حُورًا! کہ اللہ تجھے پرندے کا گوشت کھلائے اور تیری شادی حوروں سے کرے۔ لیکن یہ رسول اکرم صلی اللہ علیہ وسلم سے ثابت نہیں۔ اصل میں کوئی احسان کرے تو اسے اس کی مثل صلہ دیا جائے یا اس سے زیادہ دیا جائے۔ یہ صلہ لوگوں کے حسب حال دیا جائے۔ بعض لوگ بہت زیادہ مال و دولت والے ہوتے ہیں اور قوم میں جاہ و جلال اور شرف و فضل والے ہوتے ہیں اگر یہ کسی سے حسن سلوک کرتے ہیں تو یہ اس کا صلہ مال کی صورت میں نہیں لینا پسند کرتے ایسے افراد کے لیے صلہ نہ دیں صرف دعائے خیر کر دیں۔ (شرح عثیمین: ۱۲۶۸)","m":"جَزَاكَ (ض) (ناقص یائی) ماضی واحد مذکر غائب۔ ضمیر مفعول بہ۔ تجھے جزا دے۔"}],[1496,"سیدنا جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اپنے بارے میں بددعاء نہ کرو، اپنی اولاد کو بددعاء نہ دو، اپنے مالوں کو بددعاء نہ دو، ایسا نہ ہو کہ اللہ کی اس گھڑی میں یہ (بددعاء) کرو، جس میں اللہ سے جو کچھ مانگا جائے اللہ تمہاری دعاء قبول کر لیتا ہے۔“ (مسلم)","",{"k":"مسلم (۳۰۰۹)۔","e":"اس میں خود کو اور اپنی اولاد کو اور مال کو بددعاء دینے کی ممانعت بیان ہوئی ہے کہ ہو سکتا ہے وہ قبولیت کی گھڑی ہو اور نقصان ہو جائے۔ کیونکہ وقت میں بھی قبولیت کی خاصیت ہوتی ہے۔ اس مبارک وقت میں اللہ تعالیٰ جلدی دعاء قبول کرتے ہیں۔ ایک مومن کو ان مبارک گھڑیوں میں دعاء کرنی چاہیے۔ لیکن وہ دعاء خیر کی، رحمت کی اور عافیت کی دعاء ہونی چاہیے۔ عذاب اور ہلاکت کی بددعاء نہیں ہونی چاہیے اور سب سے زیادہ قبولیت دعاء کی امید والا وقت رات کا آخری حصہ ہے یا فرض نمازوں کے بعد کا ہے۔ ویسے تو اللہ تعالیٰ اپنے بندوں کی دعائیں ہر وقت سنتا ہے۔ لیکن بعض اوقات ایسے ہیں جن میں اللہ تعالیٰ فوراً دعاء قبول کرتے ہیں۔ اس لیے دعاء کی ترغیب ہے بددعاء سے احتیاط کا حکم ہے۔ وجہ یہ ہے کہ انسان طبعاً جلد باز ہے ذرا سی تکلیف پر گھبرا جاتا ہے اور مایوس ہو جاتا ہے اور طیش میں آ کر بددعاء شروع کر دیتا ہے۔ اس کو جلد بازی سے روکا گیا ہے۔ ان اوقات میں اللہ تعالیٰ دعاء جلدی قبول کرتے ہیں۔ جمعہ کے دن، اذان اور اقامت کے درمیان، سجدوں میں، گھمسان کی لڑائی میں، بارش کے وقت، عرفہ کے دن، مرغ کی آواز کے وقت، میت کی آنکھیں بند کرتے وقت، قدر کی رات میں، روزہ افطار کرتے وقت دعاء قبول ہوتی ہے۔ (بہجة الناظرين: ۲/ ص ۳۶۹)","m":"لَا تُوَافِقُوا (مفاعلہ) (مثال واوی) نہی جمع مذکر حاضر۔ تم نہ موافقت کرو۔ فَيَسْتَجِيبَ (استفعال) (اجوف واوی) مضارع واحد مذکر غائب۔ فاء کے بعد اَنْ نے اسے آخر میں زبر دی ہے۔"}],[1497,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بندہ اپنے رب سے قریب ترین اس وقت ہوتا ہے جب وہ سجدے میں ہو۔ اس لئے (سجدے میں) کثرت سے دعا کرو۔“ (مسلم)","",{"k":"مسلم (۴۸۲)، احمد (۹۴۶۱)، ابوداؤد (۸۷۵)، نسائی (۲؍۲۲۶)۔","e":"علامہ عثیمین رحمہ اللہ اس حدیث کی وضاحت میں تحریر فرماتے ہیں۔ انسان جب اللہ سے دعاء کرتا ہے تو اللہ کے قریب ہو جاتا ہے۔ ارشاد باری ہے: ﴿وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ﴾ (البقرہ: ۱۸۶) اور جب تجھ سے میرے متعلق میرے بندے سوال کریں کہو۔ میں قریب ہوں۔ اور حالت سجدہ میں تو بہت ہی زیادہ بندہ اللہ کے قریب ہوتا ہے۔ وجہ یہ ہے کہ یہ حالت انتہائی خضوع والی ہے کیونکہ چہرہ جو کہ سب اعضاء سے اشرف و اعلیٰ ہے اسے اللہ کی کبریائی کے سامنے پاؤں والی جگہ پر رکھ کر اپنے رب کی تعظیم کی جاتی ہے اس لیے یہ حالت بندے کے اللہ کے قریب ہونے اور اللہ کے بندے کے قریب ہونے کے لیے نہایت ہی موزوں ہے۔ اس میں کثرت سے دعاء کریں خواہ یہ نماز فرض ہو یا نفل ہو اور دعاء دنیوی امور کے متعلق ہو یا آخرت کے معاملہ میں ہو۔ یہ سب خیر ہے اور دعاء ہے اور دعاء عبادت ہے۔ اگر ایک آدمی یہ کہتا ہے کہ اللہ کریم میرے مال میں کثرت کر دے۔ اللہ مجھے اچھی رہائش دے، اے اللہ! مجھے آرام دہ گاڑی دے تو کوئی حرج نہیں حدیث میں بھی آتا ہے اگر جوتے کا تسمہ بھی طلب کرو تو اللہ سے مانگو۔ (ترمذی: ۳۶۰۴، ضعیف) ہر جائز چیز اللہ سے مانگنا عبادت ہے۔ اور اللہ سے مانگنا ہر حال میں مفید ہے یا تو اللہ تعالیٰ قبول کرلیں گے یا کوئی برائی دور کر دیں گے یا قیامت کے دن کے لیے ذخیرہ کر دیں گے اجر ملے گا۔ (شرح عثیمین: ۱۲۶۹)"}],[1498,"انہی سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم سے (ہر) ایک کی دعاء قبول کی جاتی ہے، جبکہ وہ جلدی نہ کرے۔ (یعنی) کہنے لگے۔ میں نے رب سے دعاء کی تھی تو میری دعاء قبول نہیں ہوئی۔“ (متفق علیہ) مسلم کی ایک روایت میں یہ الفاظ ہیں: بندے کی دعائیں قبول ہوتی رہتی ہیں۔ جب تک کسی گناہ والی یا قطع رحمی والی دعا نہ کرے۔ جب تک جلدی نہ مچائے۔ عرض کی گئی: اللہ کے رسول! جلدی مچانے سے کیا مراد ہے؟ فرمایا: وہ کہتا ہے: میں نے دعاء کی۔ پھر دعاء کی، (بار بار دعاء کرنے کے باوجود) مجھے وہ قبول ہوتی نظر نہیں آتی۔ تب وہ تھک کر دعاء کرنا چھوڑ دیتا ہے۔","متفق علیہ",{"k":"بخاری (۶۳۴۰)، مسلم (۲۷۳۵)، احمد (۹۱۴۸)، ترمذی (۳۳۸۴)، ابوداؤد (۱۴۸۴)۔","e":"اس میں دعاء کرنے کی ترغیب ہے کیونکہ یہ اہم عبادت ہے۔ اور اللہ تعالیٰ نے دعاء کی قبولیت کی ضمانت دی ہے اور جلد بازی انسان کو دعاء جیسی عبادت سے دور کر دیتی ہے اور تمام امور اللہ کے ہاتھ میں ہیں۔ اس نے ہر چیز کا اندازہ مقرر کیا ہے اور ہر کام کے لیے وقت مقرر ہے وہ بندوں کی جلدی مچانے سے اپنے پروگرام میں تبدیلی نہیں کرتا۔ اس لیے انسان مسلسل اللہ سے دعاء کرتا رہے یہ ہرگز نہ سوچے کہ مجھے دعاء کرتے ہوئے عرصہ ہو گیا ہے کچھ بھی نہیں ہوا، اللہ کے در سے کبھی مایوس نہ ہو۔ اگر اس میں تاخیر ہو رہی ہے تو یقیناً اس میں مصلحت ہے جس کا علم صرف اللہ کو ہے بندے کو نہیں۔ دعاء قبول ہو یا نہ ہو دعاء کرنا ترک نہ کرے اس میں انسان کا بہر صورت فائدہ ہی فائدہ ہے۔ لہذا امید ہو کر اور اللہ کے ساتھ حسن ظن سے دعاء جاری رکھی جائے۔","m":"فَلَمْ يُسْتَجَبْ: (استفعال) اجوف واوی) نفی ماضی مجہول واحد مذکر غائب۔ نہ قبول کیا گیا۔ فَيَسْتَحْسِرُ (استفعال) صحیح) مضارع معلوم واحد مذکر غائب۔ وہ اکتا جاتا ہے۔"}],[1499,"سیدنا ابو امامہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے عرض کی گئی: کون سی دعاء زیادہ سنی (اور قبول کی جاتی ہے؟ فرمایا: ”رات کے اندر، اس کے آخری حصے میں، اور فرض نمازوں کے آخر میں۔“ (ترمذی۔ انہوں نے فرمایا: یہ حدیث حسن ہے۔)","حسن",{"k":"ترمذی (۳۴۹۹)۔\nنسائی عمل الیوم واللیلة: ۱۰۸۔","e":"اس میں بیان ہوا ہے کہ دعاء کی قبولیت کے امید افزا یہ دو مقام بتائے گئے ہیں۔ رات کا آخری پہر اور پانچ فرض نمازوں کے بعد دعاء قبول ہوتی ہے۔ اس وقت ہر طرف سناٹا ہوتا ہے اور یہ شخص بیدار ہوکر آسمان اور زمین کی پیدائش پر غور کرتا ہے اور اپنے دل میں اپنے خالق کی عظمت بٹھاتا ہے اور اپنی حاجات اس کے سامنے پیش کرتا ہے اور اللہ کی رحمت کی امید رکھتے ہوئے اس کے سامنے دست سوال دراز کرتا ہے۔ اللہ تعالیٰ بھی ان جیسے لوگوں کی تعریف کرتا ہے۔ ﴿كَانُوا قَلِيلًا مِنَ اللَّيْلِ مَا يَهْجَعُونَ ○ وَبِالْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ﴾ (الذاریات: ۱۷-۱۸) یہ رات کو کم سوتے تھے اور سحری کے وقت استغفار کرتے تھے اور فرض نمازوں کے سلام پھیرنے کے بعد دعاء کی قبولیت کا امکان زیادہ ہے۔ ایک قول ہے یہ تشہد اور درود پڑھنے کے بعد اور سلام پھیرنے سے پہلے کا وقت ہے۔ یہ بھی ممکن ہے لیکن زیادہ بہتر سلام پھیرنے کے بعد کا وقت ہے۔ فرماتے ہیں نماز کے سلام کے بعد دعاء کرنا مراد نہیں کیونکہ سلام کے بعد دعاء کا محل نہیں وہ تو ذکر کا محل ہے۔ ارشاد باری ہے: ﴿فَإِذَا قَضَيْتُمُ الصَّلَاةَ فَاذْكُرُوا اللَّهَ قِيَامًا وَقُعُودًا وَعَلَى جُنُوبِكُمْ﴾ (النساء: ۱۰۳) اور جب تم نماز پوری کر لو تو اللہ کا ذکر کرو کھڑے ہو کر اور بیٹھ کر اور اپنے پہلوؤں پر اللہ کا ذکر کرو۔ (شرح: ۱۲۷۰) راقم کہتا ہے نماز کے بعد اگر چہ محل ذکر ہے لیکن دعاء بھی تو ذکر ہے یہ بھی مراد ہوسکتی ہے۔ باقی اجتماعی طور پر ہاتھ اٹھا کر با قاعدہ دعاء کا التزام درست نہیں اسے لازم نہ سمجھا جائے اور کبھی کر لی اور کبھی چھوڑ دی تو اس کی گنجائش ہے۔ اور رات کے پچھلے پہر وہ حقیقی داتا خود اپنے بندوں کو پکار رہا ہوتا ہے۔ حدیث میں آتا ہے۔ نبی صلی اللہ علیہ وسلم نے فرمایا، رات کے آخری تیسرے حصے میں اللہ تعالی فرماتے ہیں۔ کون ہے جو مجھ سے دعاء کرے میں اسے قبول کروں گا۔ اور کون ہے جو مجھ سے مانگے میں اسے دوں۔ اور طلب کرے میں اسے مغفرت سے نوازوں۔ (بخاری: ۱۱۴۵۔ مسلم: ۱۷۷۲۔ احمد: ۱۰۳۱۳) ان اوقات سے غافل نہ ہوں اللہ کی بارگاہ میں دعائیں کریں اور سعادت مندی دامن میں سمیٹ لیں۔ انتباہ: اس کی سند میں ابن سابط ہے اس نے ابو امامہ رضی اللہ عنہ سے نہیں سنا جس کی وجہ سے یہ ضعیف ہے۔ لیکن اس کا شاہد (تائید کرنے والی حدیث) موجود ہے۔ ترمذی: ۳۵۶۰ میں نسائی: ۱/ ص ۱۷۹ میں اور حاکم: ۱/ ص ۲۰۹ میں یہ شاہد ہے۔ اور حاکم نے اسے صحیح کہا ہے۔ ابن خزیمہ نے بھی اسے صحیح کہا ہے۔ اور ذہبی نے موافقت کی ہے۔ لہذا شواہد کی بناء پر یہ حدیث کم از کم حسن درجہ کی ہے۔ (بھجة الناظرین: ۲/ ص ۳۷۱)"}],[1500,"سیدنا عبادہ بن صامت رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”روئے زمین پر کوئی بھی مسلمان اللہ تعالی سے جو بھی دعاء کرتا ہے، اللہ تعالی اُسے وہ چیز دے دیتا ہے، یا اُس سے ویسی ہی بُرائی (مصیبت، موجودہ یا آئندہ تکلیف) دور کر دیتا ہے۔ جب وہ گناہ والی یا قطع رحمی والی دعا نہ کرے۔ حاضرین میں سے ایک صاحب نے کہا: تب تو ہم کثرت سے دعائیں کریں گے۔ آنحضرت صلی اللہ علیہ وسلم نے فرمایا: اللہ کے پاس اس سے بھی زیادہ ہے۔“ (اسے ترمذی نے روایت کر کے فرمایا: یہ حدیث حسن صحیح ہے۔ اسے حاکم نے سیدنا ابو سعید رضی اللہ عنہ کی روایت سے درج کیا ہے اور اس روایت میں یہ جملہ بھی ہے۔ یا اس کے لئے اتنا ثواب ذخیرہ کر لیتا ہے۔“","حسن صحیح",{"k":"ترمذی (۳۵۷۳)، مستدرک حاکم (۱؍۴۹۳)، احمد (۲۲۷۸۵)۔\nترمذی میں ہی جابر سے بھی روایت ہے ۳۳۷۸۔","e":"یعنی اگر گناہ والی دعاء نہ ہو تو یہ قبول ہوتی ہے تو ہم یہ دعائیں کثرت سے کریں گے تو آپ صلی اللہ علیہ وسلم نے فرمایا، جو تم دعاء کرو گے اللہ تعالی اس سے بھی زیادہ احسان کرنے والے ہیں اور عطیات سے نوازتے ہیں اور جو لوگ اللہ سے مانگتے ہیں اور درخواست کرتے ہیں اللہ کے پاس اس سے کہیں زیادہ ہے اس لیے انسان اس سے مانگے بار بار مانگے نہ اس کا خزانہ ختم ہوتا ہے نہ ہی وہ اکتا تا ہے۔ یہ شرط ہے گناہ کی دعاء نہ ہو یہ منع ہے یہ قبول نہیں ہوتی ہے اور دعاء میں خضوع اور لاچاری ہو اور اللہ کے حضور تضرع اور محتاجی کے ساتھ دعاء کی جائے وہ خزانوں کا مالک ہے وہ رات دن خرچ کرتا ہے اس کے خزانے میں ایک دانے کی بھی کمی نہیں آتی۔ اللہ تعالی جتنی شان و شوکت والا ہے اس کے مطابق ہی اس سے مانگا جائے۔"}]]);
